export type StaffSummaryDto = {
  /**
   * Staff record ID.
   */
  id: string;
  /**
   * Staff record ID — the §5.3 field name. `id` carries the same value for older clients.
   */
  staffId: string;
  /**
   * Staff login email.
   */
  email: string;
  /**
   * Display name, built as `lastName firstName`.
   */
  name: string;
  /**
   * Family name.
   */
  lastName: string;
  /**
   * Given name.
   */
  firstName: string;
  /**
   * Family name kana.
   */
  lastNameKana: string | null;
  /**
   * Given name kana.
   */
  firstNameKana: string | null;
  /**
   * Position master ID. The role's 未割当 position when the staff has not been assigned one yet.
   */
  positionId: string;
  /**
   * Position master name (`未割当` while unassigned).
   */
  positionName: string;
  /**
   * CRM role inherited from the staff's position.
   */
  role: 'system' | 'headquarter' | 'manager' | 'staff' | 'trainer' | 'observer';
  /**
   * Which half of the stores / fcCompanyId XOR pair is set.
   */
  affiliationType: 'store' | 'fc_company';
  /**
   * The staff's stores (所属店舗 — multi-select for every role since Dev Q&A 2026-11-07; there is no separate primary store). `storeId` comes first. Empty for FC staff (pattern B, see `fcCompanyId`). For a manager this is also its store scope.
   */
  storeIds: Array<string>;
  /**
   * The same stores as `storeIds`, same order, with name / code / area for the 所属店舗 column.
   */
  stores: Array<StaffStoreRefDto>;
  /**
   * The FIRST of `storeIds` (kept for single-store clients; read `storeIds` for the set). Null for FC staff (mutually exclusive with `fcCompanyId`).
   */
  storeId: string | null;
  /**
   * Store name, resolved from contracts-svc. Null when the staff is FC-affiliated, or when the name could not be resolved (the list still renders).
   */
  storeName: string | null;
  /**
   * Store code, from the same contracts-svc lookup as `storeName`. Same null semantics.
   */
  storeCode: string | null;
  /**
   * Store area (`stores.area`) — the value the `area` filter matches. Same null semantics as `storeName`.
   */
  storeArea: string | null;
  /**
   * FC company. Null for store staff (mutually exclusive with `storeId`).
   */
  fcCompanyId: string | null;
  /**
   * FC company name, resolved from contracts-svc. Same null semantics as `storeName`.
   */
  fcCompanyName: string | null;
  /**
   * Number of `staff_stores` rows. Since the multi-store change these are the staff's stores for every role, so this is normally `storeIds.length`; prefer that.
   */
  managedStoreCount: number;
  /**
   * The staff lifecycle badge — 有効 / 無効 / 招待中. **Bind this value directly**; do not re-derive it. `inactive` = deactivated (this wins even when onboarding never finished); `invited` = the first login has not completed, and stays `invited` past the 72-hour token expiry until re-invite; `active` = both done. The `status` query parameter filters on exactly this, and `sort=status` orders by it.
   */
  status: 'active' | 'inactive' | 'invited';
  /**
   * Raw `staffs.is_active`. Narrower than `status`, which also accounts for whether onboarding completed — a staff can be `isActive: true` and still `invited`.
   */
  isActive: boolean;
  /**
   * Last successful CRM login (ISO 8601 UTC, absolute — format relative text like "3 days ago" client-side). Null = never logged in, always null while `invited`. Also null for staff who last logged in before this field existed.
   */
  lastLoginAt: string | null;
  /**
   * Most recent invitation timestamp (ISO 8601 UTC); re-inviting updates it. Null only if no invite record remains — show "—".
   */
  invitedAt: string | null;
  /**
   * When the staff was deactivated (ISO 8601 UTC). Null while active, and on rows deactivated before the column existed.
   */
  deactivatedAt: string | null;
  /**
   * 無効化理由 — the free text captured at deactivation. Null while active, and on rows deactivated before the column existed.
   */
  deactivatedReason: string | null;
  /**
   * The newest invitation and its state. Null when the staff has never been invited. `invitedAt` above is the same timestamp, kept flat for the list column.
   */
  invite: StaffInviteStateDto | null;
};

