export type StaffLoginHistoryItemDto = {
  /**
   * `staff_login_histories.id` (UUID v7).
   */
  id: string;
  /**
   * Attempt timestamp, UTC. MAX over the `success` rows is `staffs.last_login_at` — a refused attempt deliberately does not move it.
   */
  loggedInAt: string;
  /**
   * Y-13 FR-M009 結果 — 成功 / 失敗 / ロック.
   *
   * `failure` covers the refusals fitness-api can see AND attribute to someone: unregistered account (`E-AUTH-033`), deactivated account (`E-AUTH-034`), an email domain outside the Y-14 allowlist (`E-DMN-007`), an expired CRM magic link (`E-AUTH-030`).
   *
   * **A wrong password is NOT among them.** The CRM authenticates against Cognito directly (SRP), so a failed password produces no request to this backend — see API-069 §3.4. The same holds for Google Workspace, which FR-M008 itself leaves to Google.
   *
   * `lock` is defined but never written yet: Cognito locks an account internally and publishes no event for it, and there is no unlock API to pair with FR-M008 either.
   */
  result: 'success' | 'failure' | 'lock';
  /**
   * FR-M009 記録項目 メールアドレス — the address the attempt was made with. On a refusal this need not equal the address on the staff record the row is filed under. `null` on rows written before migration 040.
   */
  email: string | null;
  /**
   * Which refusal it was: `E-AUTH-033` / `E-AUTH-034` / `E-DMN-007` / `E-AUTH-030`. `null` when `result` is `success`. Beyond FR-M009, which asks only for 結果 — a bare 失敗 gives the operator nothing to act on.
   */
  failureReason: string | null;
  /**
   * Which sign-in lane was used. `null` when not captured.
   */
  authProvider: 'google' | 'cognito' | 'magic_link';
  /**
   * The Redis session this login created, so a forced logout traces to the session it ended. Compare against the caller's own `sessionId` to mark 現在のセッション. Always `null` when `result` is not `success` — a refused attempt opens no session.
   */
  sessionId: string | null;
  /**
   * Source IP. `null` when unavailable.
   */
  ipAddress: string | null;
  /**
   * Raw User-Agent header. `null` when unavailable.
   */
  userAgent: string | null;
};

export type StaffLoginHistoryListResponseDto = {
  /**
   * Sign-in attempts on this page, newest first (`logged_in_at DESC`, not client-sortable). Successes and refusals are interleaved — read `result` per row.
   */
  items: Array<StaffLoginHistoryItemDto>;
  pagination: PaginationWithPageItemsDto;
};

