export type RegisterDomainMasterDto = {
  /**
   * Management name (管理名) — Y-14 FR-M002 required item. Identifies the row in the list and in the deletion dialog.
   */
  name: string;
  /**
   * Email domain (RFC 1035). The part after `@` of a staff email, without the `@`: at least two labels, an alphabetic TLD, no scheme or trailing dot. Anything else (`test.2`, `@example.co.jp`, `https://example.co.jp`) is `400 E-VAL-001` with `details[].code = invalid_format`, because no staff email at it could pass invitation (API-070). A label (the text between dots) over 63 characters is reported on its own as `{ field: "domain", code: "too_long" }`. At most 252 characters, or 126 when `authProvider` is `cognito` (the route's email limit minus 2, so `a@<domain>` fits); over it is `400 E-VAL-001` with `details[]` = `{ field: "domain", code: "too_long" }`. Normalized to lowercase server-side; must be unique (E-DMN-001).
   */
  domain: string;
  /**
   * Authentication route for this domain. UI labels: `google` → Google SSO, `cognito` → IDaaS. Applied at invitation (API-070) and at login (API-069) as the stored value.
   */
  authProvider: 'google' | 'cognito';
};

