export type UpdateDomainMasterDto = {
  /**
   * New management name. **Always editable**, even while staff are attached.
   */
  name?: string;
  /**
   * New email domain. The part after `@` of a staff email, without the `@`: at least two labels, an alphabetic TLD, no scheme or trailing dot. Anything else (`test.2`, `@example.co.jp`, `https://example.co.jp`) is `400 E-VAL-001` with `details[].code = invalid_format`, because no staff email at it could pass invitation (API-070). A label (the text between dots) over 63 characters is reported on its own as `{ field: "domain", code: "too_long" }`. **Blocked while active staff are attached** (E-DMN-005). The 252 / 126 limit is checked on the domain and authProvider after the change, only when either actually changes (after E-DMN-005, before E-DMN-001): `400 E-VAL-001` `{ field: "domain", code: "too_long" }`.
   */
  domain?: string;
  /**
   * New authentication route. **Blocked while active staff are attached** (E-DMN-005). Switching to `cognito` is refused when the domain is longer than 126 characters (`400 E-VAL-001` on `domain`).
   */
  authProvider?: 'google' | 'cognito';
};

