  /**
   * Prefecture. Null when unset.
   */
  prefecture: string | null;
  /**
   * **Always null.** The v2 member row has ONE `prefecture` column that holds either the JIS X 0401 code or the name, with no separate code column — deriving one would be guessing which form the stored value is in.
   */
  prefectureCode: string | null;
  /**
   * **Always null** — v2 stores no city component at all (see `city`).
   */
  cityCode: string | null;
  /**
   * **Always null** — the new model stores one `street_address` with no separate city component.
   */
  city: string | null;
  /**
   * Street address — the whole line, since `city` is not split out.
   */
  address1: string | null;
  /**
   * Building / room. Null when unset.
   */
