  /**
   * Gender, under the legacy field name `sex`.
   */
  sex: string | null;
  /**
   * Date of birth. Null when unset.
   */
  birthDate: string | null;
  /**
   * The **backend** member lifecycle status — not the mobile `MemberStatus` enum that `members/verify` returns.
   */
  status: string | null;
  /**
   * Creation timestamp.
   */
  createdAt: string | null;
  /**
   * Last-update timestamp.
   */
