  /**
   * When the job started running (ISO 8601 UTC). Null while pending.
   */
  startedAt: string | null;
  /**
   * When the job finished (ISO 8601 UTC). Null until it terminates.
   */
  completedAt: string | null;
  /**
   * Staff that queued the job. Null for system-created jobs.
   */
