  /**
   * Given name in katakana. Null when unset.
   */
  firstNameKana: string | null;
  /**
   * Gender. Null when unset.
   */
  gender: string | null;
  /**
   * Date of birth. Null when unset.
   */
  dateOfBirth: string | null;
  /**
   * Email. Null when unset or anonymized.
   */
  email: string | null;
  /**
   * Phone, E.164 as stored (v0.14 — a number under another country code is returned as is, e.g. `+84…`). Null when unset or anonymized.
   */
