  source: 'application' | 'bulk_job';
  /**
   * The application ID or the bulk job ID, per `source`.
   */
  sourceId: string;
  /**
   * Apply-from date. Always the first of a month.
   */
  scheduledChangeDate: string;
  /**
   * The plan the contract will move to. `name` / `code` are null for a bulk reservation — the job stores only the plan id.
   */
