export type MemberPaymentDto = {
  id: string;
  /**
   * Which side of the ledger the row is (the 種別 column). `payment` = money in, `refund` = money out. The two come from different tables — a refund is NOT a negative `payments` row — so the payment fields below are null on a `refund` row and the refund fields are null on a `payment` row. Same vocabulary as the F-01 ledger (API-116 §7).
   */
  transactionType: 'payment' | 'refund';
  /**
   * Billing this attempt paid; null for an unallocated payment.
   */
  billingId: string | null;
  /**
   * JPY. Positive on a `payment` row (money in), NEGATIVE on a `refund` row (money out) — BR-TXN-006, so the tab can sum to a running balance.
   */
  amount: number;
  /**
   * billings.dbml `payment_method`. Same value set as the `paymentMethod` filter. Null on a `refund` row — see `refundMethod`.
   */
  paymentMethod:
    | 'sbps_credit'
    | 'jaccs_bank'
    | 'cash'
    | 'card_onsite'
    | 'convenience_store'
    | 'sbps_link'
    | 'cashpost'
    | 'bank_transfer'
    | 'manual';
  /**
   * billings.dbml `payment_status`. This used to advertise only 3 of the 7 values, so a `refunded` row looked like a contract violation to the client. Null on a `refund` row — see `refundStatus`.
   */
  paymentStatus:
    | 'pending'
    | 'processing'
    | 'success'
    | 'failed'
    | 'cancelled'
    | 'refunded'
    | 'partial_refund';
  /**
   * `refunds.refund_method` — how the money went back. Null on a `payment` row.
   */
  refundMethod: 'sbps_cancel' | 'bank_transfer' | 'cash' | 'offset';
  /**
   * `refunds.status`. Null on a `payment` row. Only `succeeded` has actually moved money — a `pending` row is an approved application that has not run yet. These are the values the writer stores; the DBML column comment (`executing` / `executed`) is stale.
   */
  refundStatus: 'pending' | 'succeeded' | 'failed';
  /**
   * `payments.paid_at`, or `refunds.refunded_at` on a `refund` row — the date column of the tab.
   */
  paidAt: string | null;
  failedAt: string | null;
  /**
   * Gateway reason on a failed attempt.
   */
  failureReason: string | null;
  receiptNumber: string | null;
  /**
   * The 内容 column, trimmed to 200 chars: `payments.description` (F-01 free text) on a `payment` row, and the operator's 返金事由 (`refund_applications.reason`) on a `refund` row. Null on rows written before the column landed.
   */
  description: string | null;
  /**
   * Store the payment belongs to (`payments.store_id` → stores, current name — not point-in-time). Null when the store is unknown or contracts-svc did not answer.
   */
  storeName: string | null;
  /**
   * When the attempt was made.
   */
  createdAt: string;
};

export type MemberPaymentSummaryDto = {
  /**
   * 売上合計 — sum of the `success` payments among the filtered rows whose `paidAt` falls in the window. Same definition as API-114 `paymentTotal` (tax-inclusive). 0 under `transactionType=refund`.
   */
  salesTotal: number;
  /**
   * 返金合計 — sum of the `succeeded` refunds among the filtered rows whose `refundedAt` falls in the window, as a POSITIVE number; the card renders its own minus sign. 0 under `transactionType=payment` or a `paymentMethod` / `paymentStatus` filter, which leave no refund row in the ledger.
   */
  refundTotal: number;
  /**
   * 差引合計 = salesTotal − refundTotal.
   */
  netTotal: number;
  /**
   * 最終入金日 — the latest `paidAt` among the rows counted in `salesTotal`. Null when nothing was collected among the filtered rows (always under `transactionType=refund`).
   */
  lastPaidAt: string | null;
};

export type MemberPaymentPageDto = {
  /**
   * The ledger: payments (successful AND failed) and refunds, newest first.
   */
  items: Array<MemberPaymentDto>;
  /**
   * The 支払いサマリー card. Present only when the request carried `includeSummary=true`. Totals the rows the ledger filters select — the `from`/`to` window AND `transactionType` (the 種別 select) / `paymentMethod` / `paymentStatus` — so the card moves with the table beside it: `transactionType=refund` answers `salesTotal: 0` and `lastPaidAt: null`. `page` / `limit` / `sort` never move it (it is dated on `paidAt` / `refundedAt`). It cannot be summed client-side: the list is paginated.
   */
  summary?: MemberPaymentSummaryDto;
  /**
   * `totalAllItems` is present only when the request carried `includeTotalAll=true`. For this union the baseline counts BOTH sources.
   */
  pagination: PaginationWithTotalAllDto;
};

