export type SuspWdrDetailDto = {
  /**
   * Which application type this is.
   */
  applicationType: 'suspension' | 'withdrawal';
  /**
   * Application ID.
   */
  applicationId: string;
  /**
   * Human-readable application number. Null when unnumbered.
   */
  applicationNumber: string | null;
  /**
   * The **application** status (unlike `displayStatus`, which is the member’s).
   */
  status: string;
  /**
   * API-092 §4.3/§5.3 `displayStatus` — the §3.4 display state while the row is listable; null once the application is completed / cancelled (closure is shown by `status`).
   */
  displayStatus: string | null;
  member: ApplicantMemberDto;
  /**
   * API-092 §4.3/§5.3 `store` — the contract’s store, resolved from contracts-svc. Null when the member has no current contract.
   */
  store: SuspWdrStoreDto | null;
  /**
   * Reason code supplied on the application. Null when unset.
   */
  reasonCode: string | null;
  /**
   * Fee snapshot taken at filing, **tax-included (税込)** (API-087 v0.14; older rows converted by auth migration 051) — 休会費 (`plans.suspension_fee`) on a suspension, 解約手数料 on a withdrawal (API-092 §4.3 / §5.3). Null on rows filed before the snapshot lanes were wired.
   */
  fee: number | null;
  /**
   * Effective date. **The key name varies by type** — the service spreads a type-specific date map, so a withdrawal carries `scheduledDate` while a suspension carries its own start/end keys.
   */
  scheduledDate?: string | null;
  /**
   * When the application was filed (ISO 8601 UTC).
   */
  appliedAt: string;
  /**
   * Proxy filing, shaped as `{ proxyStaff: { staffId } }`. Null for member-initiated applications.
   */
  proxy: {
    [key: string]: unknown;
  } | null;
  /**
   * API-092 §4.3/§5.3 `proxyStaff` — the staffer who filed on the member’s behalf (proxy / crm_direct). Null for mobile_app filings.
   */
  proxyStaff: StaffRefDto | null;
  /**
   * 合意日時 (when the member agreed) — required on the proxy route, else null.
   */
  proxyAgreedAt: string | null;
  /**
   * 合意方法 (how the member agreed). Null on non-proxy rows and legacy rows.
   */
  proxyAgreementMethod: 'in_person' | 'phone' | 'email' | 'line';
  /**
   * API-092 §4.4/§5.4 approval-flow Timeline: applied → approval → (recess_start → recess_end | execution), each completed / current / pending.
   */
  timeline: SuspWdrTimelineDto;
  /**
   * API-092 §4.3/§5.3 `statusHistories` — raw status transitions, oldest first. `metadata.ip` / `user_agent` are never returned.
   */
  statusHistories: Array<SuspWdrStatusHistoryDto>;
  /**
   * Whether the withdrawal can still be cancelled (API-092 §5.3, server-derived from the §6.4 guard chain). **Withdrawal detail only** — the key is absent on suspension detail.
   */
  cancellable?: boolean;
  /**
   * API-092 §5.3: first blocking §6.4 condition when `cancellable=false`; null when cancellable. **Withdrawal detail only.**
   */
  cancellationBlockedReason?:
    | 'not_cancellable_status'
    | 'batch_processing_started'
    | 'usage_started';
  /**
   * API-092 §5.3 spec key (= `applicationId`). Withdrawal detail only.
   */
  withdrawalApplicationId?: string;
  /**
   * API-092 §4.3 spec key (= `applicationId`). Suspension detail only.
   */
  suspensionApplicationId?: string;
  /**
   * The main contract the application is filed against.
   */
  contractId: string | null;
  /**
   * API-092 §4.3 `applicationSource` — how the application was filed.
   */
  applicationSource: 'mobile_app' | 'crm_direct' | 'proxy' | 'system';
  /**
   * Free-text reason entered on the application (退会理由 / 休会理由).
   */
  reason: string | null;
  /**
   * API-092 §5.3 spec key for the scheduled withdrawal date (= `scheduledDate`). Withdrawal only.
   */
  scheduledWithdrawalDate?: string | null;
  /**
   * Recess start (§4.3). Suspension only.
   */
  startDate?: string | null;
  /**
   * Recess end (§4.3). Suspension only.
   */
  endDate?: string | null;
  /**
   * §5.3 withdrawal questionnaire response (G-04 / API-090). Withdrawal only.
   */
  questionnaireResponseId?: string | null;
  /**
   * §5.3 family members auto-withdrawn with this application (BR-WDR-004). Withdrawal only.
   */
  familyAutoWithdrawalCount?: number;
  /**
   * §5.3 `contracts.usage_start_date` — the FR-002 cancel-guard input, surfaced for the UI. Withdrawal only.
   */
  usageStartDate?: string | null;
  /**
   * §4.3 — set only on temporary_recess rows (bulk job). Suspension only.
   */
  notificationId?: string | null;
  /**
   * §4.3 — set only on temporary_recess rows (bulk job). Suspension only.
   */
  publishContent?: string | null;
  /**
   * §4.3/§5.3 `createdBy` — the CRM operator; null for mobile_app filings.
   */
  createdBy: StaffRefDto | null;
  /**
   * §4.3/§5.3 関連情報 (related info) — arrears, recess fee, campaign, unused lessons.
   */
  relatedInfo: SuspWdrRelatedInfoDto;
};

