export type LockerSlotSizeDto = {
  /**
   * Width in cm. Null when not recorded.
   */
  widthCm: number | null;
  /**
   * Height in cm. Null when not recorded.
   */
  heightCm: number | null;
  /**
   * Depth in cm. Null when not recorded.
   */
  depthCm: number | null;
};

export type LockerSlotDto = {
  /**
   * Slot ID.
   */
  id: string;
  /**
   * Slot code as printed on the locker.
   */
  slotCode: string;
  /**
   * Display status. `cleaning` is derived from a released-but-uncleaned slot rather than stored.
   */
  status: string;
  /**
   * Physical dimensions. Always present, though each field is independently nullable.
   */
  size: LockerSlotSizeDto;
  /**
   * Monthly fee (tax-included) of the slot's effective fee option — its own feeOptionId, else the cabinet default (API-136 §6.3 v0.4). `0` when the slot has no fee option (then `optionId` is null); never null.
   */
  fee: number;
  /**
   * Tax rate for the fee. `0` when the slot has no fee option; never null.
   */
  taxRate: number;
  /**
   * The slot's effective fee option — the option a request for this slot must carry (API-101 §6.1 #5.2 / API-098 §5.2). Null when the slot has no fee option — it cannot be rented through the normal flow.
   */
  optionId: string | null;
};

export type LatestEntryDto = {
  /**
   * When they entered (ISO 8601 UTC).
   */
  enteredAt: string;
  /**
   * The store entered.
   */
  storeId: string;
  /**
   * Store name. **Null rather than a placeholder** when the store row has gone missing — render it as absent, not as a store called "unknown".
   */
  storeName: string | null;
};

export type EntryStreakDto = {
  /**
   * JST dates with at least one allowed entry, newest first.
   */
  visitDates: Array<string>;
  /**
   * Number of distinct visit days — the length of `visitDates`, not the number of entries.
   */
  totalVisitDays: number;
};

export type TrialVisitStoreDto = {
  /**
   * The store. **Only the id** — the name is not resolved here (TODO(upstream): needs contracts-svc).
   */
  storeId: string;
};

export type TrialVisitDto = {
  /**
   * Trial visit ID.
   */
  trialVisitId: string;
  /**
   * Booking state. `permitted` allows entry; `bl_matched_waiting` is parked for staff review; `scheduled` is the neutral default.
   */
  status: string;
  /**
   * Window start (ISO 8601 UTC).
   */
  scheduledStartAt: string;
  /**
   * Window end — always exactly 30 minutes after the start.
   */
  scheduledEndAt: string;
  /**
   * The store, as an id-only object.
   */
  store: TrialVisitStoreDto;
  /**
   * Whether time-limited gate entry was requested. **Derived** as `status === "permitted"`, not stored separately.
   */
  timeLimitedEntryRequested: boolean;
  /**
   * Booking timestamp.
   */
  createdAt: string;
};

export type CreatedTrialVisitDto = {
  /**
   * Trial visit ID.
   */
  trialVisitId: string;
  /**
   * Booking state. `permitted` allows entry; `bl_matched_waiting` is parked for staff review; `scheduled` is the neutral default.
   */
  status: string;
  /**
   * Window start (ISO 8601 UTC).
   */
  scheduledStartAt: string;
  /**
   * Window end — always exactly 30 minutes after the start.
   */
  scheduledEndAt: string;
  /**
   * The store, as an id-only object.
   */
  store: TrialVisitStoreDto;
  /**
   * Whether time-limited gate entry was requested. **Derived** as `status === "permitted"`, not stored separately.
   */
  timeLimitedEntryRequested: boolean;
  /**
   * Booking timestamp.
   */
  createdAt: string;
  /**
   * Blacklist screening outcome. Drives whether `status` came back `permitted`, `bl_matched_waiting`, or `scheduled` after a match failure. **Create-only** — the list does not carry it.
   */
  blacklistMatchResult: string | null;
};

export type CancelledTrialVisitDto = {
  /**
   * The cancelled visit.
   */
  trialVisitId: string;
  /**
   * Always `cancelled`. Note this route returns **200 with a body**, not 204.
   */
  status: string;
};

export type TransferVerifyDto = {
  /**
   * true only when `blockers` is empty (API-142 §6.1 EP-C). An `E-TRF-007` fee-period notice makes it false; EP-B still accepts the submit.
   */
  verifiable: boolean;
  /**
   * Error codes for every constraint that applies, deduplicated. `[]` when nothing is in the way.
   */
  blockers: Array<
    'E-STR-001' | 'E-TRF-006' | 'E-TRF-008' | 'E-MEM-205' | 'E-TRF-009' | 'E-TRF-007'
  >;
};

export type MeasurementTrendPointDto = {
  /**
   * Bucket key — a **JST day** normally, but the **first of the month** when `date=1_year`.
   */
  date: string;
  /**
   * Mean of the indicator across that bucket, 1dp — not a single reading.
   */
  value: number;
};

export type MeasurementTrendResponseDto = {
  /**
   * Japanese display name of the indicator.
   */
  name: string;
  /**
   * Display unit.
   */
  unit: string;
  /**
   * The most recent non-zero value in the window. **0 when the window holds no usable reading** — not null.
   */
  total: number;
  /**
   * Change across the window: `first − last` for weight and muscle mass, but a **percentage** change for `bodyFatPercentage`. 0 when there are fewer than two points. Note the sign convention — a *drop* in value gives a positive number.
   */
  during: number;
  /**
   * Buckets in ascending date order. Only days with a reading appear — **not zero-filled**.
   */
  data: Array<MeasurementTrendPointDto>;
};

