export type TrainingSessionDto = {
  /**
   * Session ULID.
   */
  id: string;
  /**
   * Owning member. Always the caller — another member’s session is 403 E-AUTH-100.
   */
  memberId: string;
  /**
   * Session state. Only `active` sessions accept edits; at most one active session exists per member.
   */
  status: 'active' | 'completed' | 'abandoned';
  /**
   * Member-supplied session name (legacy `trainings.title`, board STT 53). Set only by the beginner-mode record-post screen via `PATCH /api/v1/fitness-member/trainings/{trainingId}`; null otherwise. Distinct from `routineName` — renaming a session does not relabel its routine.
   */
  title: string | null;
  /**
   * Routine this session was started from (API-022). Null for a quick-start session.
   */
  routineId: string | null;
  /**
   * Display name of that routine. Null for a quick-start session, or when the routine has since been deleted.
   */
  routineName: string | null;
  /**
   * Start timestamp (ISO 8601 UTC).
   */
  startedAt: string;
  /**
   * End timestamp. Null while the session is active.
   */
  endedAt: string | null;
  /**
   * Effective duration in seconds: the member’s manual override when `durationEdited` is true, otherwise `endedAt − startedAt`. **Null while active** — there is no live elapsed time here.
   */
  durationSeconds: number | null;
  /**
   * Whether the duration was manually overridden via `PATCH /{sessionId}/duration`.
   */
  durationEdited: boolean;
  /**
   * Exercises, ascending by `orderIndex`.
   */
  exercises: Array<SessionExerciseDto>;
  /**
   * Row creation timestamp.
   */
  createdAt: string;
  /**
   * Last-update timestamp.
   */
  updatedAt: string;
};

