  /**
   * Display name (Japanese).
   */
  name: string;
  /**
   * Whether a set of this type records a weight. False for e.g. bodyweight or duration-only types.
   */
  requiresWeight: boolean;
  /**
   * Whether a set of this type records a rep count.
   */
  requiresReps: boolean;
  /**
   * Whether a set of this type records a duration. True for planks, holds and similar.
   */
