export type EnergyDailyResponseDto = {
  /**
   * The JST day computed. Defaults to today.
   */
  date: string;
  /**
   * Whether a weight was available. False makes every derived kcal figure unreliable or null — show a "set your weight" state rather than zeroes.
   */
  isCalculable: boolean;
  /**
   * Weight used, in kg. Null when none could be resolved.
   */
  weightKg: number | null;
  /**
   * Where the weight came from: `body_records` (latest record up to end of day) or `profile` (fallback). Null alongside a null weight.
   */
  weightSource: string | null;
  /**
   * Basal metabolic rate in kcal. Null when neither measured nor estimable.
   */
  bmrKcal: number | null;
  /**
   * How BMR was obtained: `body_planner` (measured, preferred) or `estimated` (NIHN formula, which additionally needs height, age and gender — so it yields null for a member missing any of those).
   */
  bmrSource: string | null;
  /**
   * Activity level used. Falls back to `level_2` when no profile exists.
   */
  activityLevel: string;
  /**
   * PAL coefficient applied to BMR.
   */
  palCoefficient: number;
  /**
   * Total daily energy expenditure (BMR × PAL) in kcal. Null when BMR is null.
   */
  tdeeKcal: number | null;
  /**
   * Calories from training. **0 (not null) on a rest day, but null whenever `isCalculable` is false** — so null here does not mean "no training", it means "no weight".
   */
  exerciseKcal: number | null;
  /**
   * Sessions behind `exerciseKcal`. **Still populated when `exerciseKcal` is null**, since the suppression is about weight, not about the sessions.
   */
  exerciseSessions: Array<EnergyExerciseSessionDto>;
  /**
   * Steps recorded for the day. Null when no step row exists.
   */
  stepCount: number | null;
  /**
   * Where the step count came from. Null alongside a null `stepCount`.
   */
  stepCountSource: string | null;
  /**
   * Walking calories, `steps × 0.04 × weightKg`. Null when either steps or weight is missing — and treated as 0 inside `totalEnergyKcal`.
   */
  walkingKcal: number | null;
  /**
   * TDEE + exercise + walking, in kcal. Null when `tdeeKcal` is null.
   */
  totalEnergyKcal: number | null;
};

