export type SleepRecordDto = {
  /**
   * Row ID (UUID v7).
   */
  id: string;
  /**
   * Owning member.
   */
  memberId: string;
  /**
   * JST calendar day, derived from **`sleepStartAt`** — a night that begins on the 3rd and ends on the 4th belongs to the 3rd.
   */
  date: string;
  /**
   * Bed time (ISO 8601 UTC).
   */
  sleepStartAt: string;
  /**
   * Wake time (ISO 8601 UTC).
   */
  sleepEndAt: string;
  /**
   * Total sleep in minutes, **server-derived** as the bed-to-wake window minus `awakeMinutes` — a client-supplied value is not used.
   */
  totalSleepMinutes: number;
  /**
   * Minutes awake in the window. Null when the source reports no stages.
   */
  awakeMinutes: number | null;
  /**
   * REM minutes. Null when unreported.
   */
  remMinutes: number | null;
  /**
   * Light-sleep minutes. Null when unreported.
   */
  lightSleepMinutes: number | null;
  /**
   * Deep-sleep minutes. Null when unreported.
   */
  deepSleepMinutes: number | null;
  /**
   * **Always null in Phase 1** — sleep scoring is not implemented. Never render a score from this.
   */
  sleepScore: number | null;
  /**
   * Where the record came from. Unlike the stage fields, this is **always overwritten** on upsert rather than preserved.
   */
  source: string;
  /**
   * Row creation timestamp.
   */
  createdAt: string;
  /**
   * Last-update timestamp.
   */
  updatedAt: string;
};

