  /**
   * The *other* member — the followee in a following list, the follower in a followers list.
   */
  memberId: string;
  /**
   * Display name. **Empty string** when that member has no social profile row.
   */
  displayName: string;
  /**
   * Avatar URL. **Empty string**, not null, when unavailable — unlike the nullable `avatarUrl` elsewhere.
   */
