export type CreatePostDto = {
  /**
   * Strength training session ID (ULID) to post — must be owned by the caller
   */
  trainingSessionId: string;
  /**
   * Required (APP-D-01 FR-M003) — the member must choose. `coach_and_self` requires an active coach (E-SNS-002)
   */
  visibility: 'everyone' | 'followers_only' | 'self_only' | 'coach_and_self';
  /**
   * Defaults to "YYYY/MM/DD トレーニング" from the session date (BR-SOC-021)
   */
  title?: string;
  /**
   * Caption (BR-SOC-022). Send null to clear.
   */
  body?: string | null;
  /**
   * Display date; defaults to the session end time
   */
  recordedAt?: string;
  /**
   * `s3Key`s of files **already uploaded**: `POST /api/v1/media/presign` with tag `social-media` → `PUT` the bytes to the returned URL → send the keys here. At most 3 images and 1 video; the type comes from the extension media-svc wrote. A key outside the `social-media` namespace is `E-SNS-008`.
   */
  mediaKeys?: Array<string>;
};

export type PostTrainingSummaryDto = {
  /**
   * Session duration in whole minutes. Null when there is no session or it has no duration.
   */
  durationMinutes: number | null;
  /**
   * Volume in kg over confirmed sets, 1dp. Null when there are no confirmed sets.
   */
  totalVolumeKg: number | null;
  /**
   * Confirmed set count. **Null rather than 0** when there are none.
   */
  totalSets: number | null;
  /**
   * **Always null — not implemented.** Do not display a calorie figure from a post.
   */
  totalCalories: number | null;
  /**
   * **Always 0 — not implemented.** PR flags are not exposed to social-svc.
   */
  prCount: number;
};

export type PostMediaDto = {
  /**
   * Media row ID.
   */
  mediaId: string;
  /**
   * Media kind. At most 4 images and 1 video per post.
   */
  mediaType: 'image' | 'video';
  /**
   * **Raw S3 key despite the field name `url`** — not fetchable as-is.
   */
  url: string;
  /**
   * Display order. The array is already sorted by it.
   */
  sortOrder: number;
};

export type SocialPostDto = {
  /**
   * Post ID.
   */
  id: string;
  /**
   * Author.
   */
  memberId: string;
  /**
   * Source weight-training session. **At most one** of the three source refs is non-null; all three null means a free post.
   */
  trainingSessionId: string | null;
  /**
   * Source aerobic session, under the same one-of-three rule.
   */
  aerobicTrainingSessionId: string | null;
  /**
   * Source running record, under the same one-of-three rule.
   */
  runningRecordId: string | null;
  /**
   * Title. Auto-generated as `YYYY/MM/DD トレーニング` (JST) when created from a training session without one.
   */
  title: string;
  /**
   * Body text (≤ 500 chars). Null when unset.
   */
  body: string | null;
  /**
   * Visibility. **Required on create** — there is no silent default (E-SNS-011). `coach_and_self` requires the member to actually have a coach.
   */
  visibility: string;
  /**
   * When the underlying activity happened — taken from the source session, not the post time.
   */
  recordedAt: string;
  /**
   * Session metrics, **derived on read** rather than snapshotted — so they follow later edits of the session.
   */
  trainingSummary: PostTrainingSummaryDto;
  /**
   * Attached media. **Always `[]` on create** — media is added afterwards via the presign endpoint.
   */
  media: Array<PostMediaDto>;
  /**
   * Like count.
   */
  likeCount: number;
  /**
   * Stamp count — reactions other than `like`.
   */
  stampCount: number;
  /**
   * Post creation timestamp.
   */
  createdAt: string;
  /**
   * Last-update timestamp.
   */
  updatedAt: string;
};

