export type InboxItemDto = {
  /**
   * Inbox item ID (a UUID string — there is no int alias layer, ADR-038 D8).
   */
  id: string;
  /**
   * Topic — the same axis the preferences use. Null for notifications that belong to no topic.
   */
  topic: string | null;
  /**
   * Notification title.
   */
  title: string;
  /**
   * Notification body.
   */
  body: string;
  /**
   * Image. **This is the one place the BFF signs a key into a fetchable URL** — notification-svc emits `imageS3Key`, and the BFF renames it to `imageUrl` after signing. Signing is best-effort: on a media-svc outage the **raw key** is returned under this same field. Null when the notification has no image.
   */
  imageUrl: string | null;
  /**
   * Deep link to open on tap. Null when the notification is informational only.
   */
  deepLink: string | null;
  /**
   * When it was delivered.
   */
  deliveredAt: string;
  /**
   * When it was read. **A one-way timestamp** — there is no un-read transition, and a repeat mark keeps the original value.
   */
  readAt: string | null;
};

export type InboxListResponseDto = {
  /**
   * Inbox items on this page, newest first.
   */
  items: Array<InboxItemDto>;
  pagination: PaginationDto;
};

