export type NotificationTypeDetailDto = {
  /**
   * Notification type ID.
   */
  id: string;
  /**
   * Stable public identifier — also the default sort key.
   */
  publicId: string;
  /**
   * Notification type code.
   */
  code: string;
  /**
   * Display name.
   */
  name: string;
  /**
   * Catalog category.
   */
  category: string;
  /**
   * Whether the type fires automatically or is sent manually.
   */
  triggerType: string;
  /**
   * Domain event that fires an auto type. Null for manual types.
   */
  triggerEvent: string | null;
  /**
   * Delivery priority.
   */
  priority: string;
  /**
   * Topic used for member-side opt-out grouping. Null when ungrouped.
   */
  topic: string | null;
  /**
   * Group heading on the member notification-settings screen. Null when ungrouped.
   */
  displayGroup: string | null;
  /**
   * Catalog default for push. Used when neither the store nor brand layer sets it.
   */
  defaultPush: boolean;
  /**
   * Catalog default for email.
   */
  defaultEmail: boolean;
  /**
   * Catalog default for SMS.
   */
  defaultSms: boolean;
  /**
   * Catalog default for the in-app inbox.
   */
  defaultInbox: boolean;
  /**
   * Catalog default for LINE.
   */
  defaultLine: boolean;
  /**
   * When true the channel flags cannot be overridden at brand or store level — a write attempting it is rejected.
   */
  channelsLocked: boolean;
  /**
   * Whether members may opt out of this type.
   */
  isUserOptoutAllowed: boolean;
  /**
   * Deduplication window in seconds. Null when the type is never deduplicated.
   */
  dedupWindowSeconds: number | null;
  /**
   * Whether the catalog entry is in use.
   */
  isActive: boolean;
  /**
   * Catalog last-update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
  /**
   * Catalog-level parameter defaults (free-form jsonb — e.g. the API-124 survey `reminder_days` lives here). Null when the type takes no parameters.
   */
  params: {
    [key: string]: unknown;
  } | null;
  /**
   * The spec requirement this type traces to. Null when untraced.
   */
  sourceFr: string | null;
  /**
   * Catalog row creation timestamp (ISO 8601 UTC).
   */
  createdAt: string;
};

export type PatchNotificationTypeDto = {
  /**
   * Dedup window. null = no window dedup (event id only); 0 = one delivery per reference_id; N = suppress repeats within N seconds. Range [0, 7776000] (90 days).
   */
  dedupWindowSeconds?: number | null;
  topic?:
    | 'visit_stamp'
    | 'points'
    | 'achievements'
    | 'training_reminder'
    | 'body_measurement_reminder'
    | 'condition_record'
    | 'follow_request'
    | 'news'
    | 'campaign'
    | 'reservation_reminder';
  displayGroup?: 'activity' | 'community' | 'info' | 'reservation';
  priority?: 'high' | 'normal' | 'low';
  /**
   * Type-specific defaults, e.g. { "reminder_days": 3 }.
   */
  params?: {
    [key: string]: unknown;
  } | null;
  /**
   * Operational ON/OFF for the whole type (FR-003).
   */
  isActive?: boolean;
  /**
   * Optimistic lock — must equal the row's current updatedAt.
   */
  expectedUpdatedAt?: string;
};

export type NotificationSettingOverrideDto = {
  /**
   * Push override. Null = inherit from the next layer down.
   */
  push: boolean | null;
  /**
   * Email override. Null = inherit.
   */
  email: boolean | null;
  /**
   * SMS override. Null = inherit.
   */
  sms: boolean | null;
  /**
   * Inbox override. Null = inherit.
   */
  inbox: boolean | null;
  /**
   * LINE override. Null = inherit.
   */
  line: boolean | null;
  /**
   * Parameter override for this layer. Null = inherit. Replaces the whole object rather than merging.
   */
  params: {
    [key: string]: unknown;
  } | null;
  /**
   * Master on/off for this layer. Null = inherit; the final fallback is `true`.
   */
  isEnabled: boolean | null;
  /**
   * When this override row last changed (ISO 8601 UTC). **Pass it back as `expectedUpdatedAt` for optimistic locking.** Null when never written.
   */
  updatedAt: string | null;
};

export type NotificationSettingEffectiveDto = {
  /**
   * Resolved push flag.
   */
  push: boolean;
  /**
   * Resolved email flag.
   */
  email: boolean;
  /**
   * Resolved SMS flag.
   */
  sms: boolean;
  /**
   * Resolved inbox flag.
   */
  inbox: boolean;
  /**
   * Resolved LINE flag.
   */
  line: boolean;
  /**
   * Resolved parameters. Null when no layer sets any.
   */
  params: {
    [key: string]: unknown;
  } | null;
  /**
   * Resolved master on/off. Falls back to `true` when no layer sets it (`layerSources.isEnabled` is then `default-true`).
   */
  isEnabled: boolean;
};

