export type UpdateRelayControllerDto = {
  /**
   * Immutable. The current value is accepted; a different value → 400 E-VAL-001.
   */
  storeId?: string;
  name?: string;
  model?: string | null;
  serialNumber?: string | null;
  location?: string | null;
  /**
   * IPv4 or IPv6. Unique per store (E-DEV-013).
   */
  ipAddress?: string | null;
  /**
   * null = 80. Outside 1–65535 → 422 E-DEV-012.
   */
  httpPort?: number | null;
  /**
   * Letters, digits and `.` `_` `-` only, at most 64 chars — else 422 E-DEV-012. null clears it.
   */
  firmwareVersion?: string | null;
  /**
   * < 1, or below the highest output port wired on this controller → 422 E-DEV-012. The device count is no bound (devices may share a port).
   */
  controlPortCount?: number | null;
  installedOn?: string | null;
  /**
   * Only `normal` is dispatched to. → `discarded` while live connected devices remain → 409 E-DEV-011. A change appends a status-history row.
   */
  status?: 'normal' | 'abnormal' | 'under_maintenance' | 'discarded';
  /**
   * AWS Secrets Manager ARN (null to detach). Bad ARN format → 422 E-DEV-012.
   */
  secretArn?: string | null;
  note?: string | null;
  /**
   * Optimistic-lock guard; 409 E-DEV-014 if stale.
   */
  expectedUpdatedAt?: string;
  /**
   * Annotates the status-history row; only meaningful alongside a `status` change (ignored otherwise).
   */
  changedReason?:
    | 'install'
    | 'fault_report'
    | 'maintenance_start'
    | 'maintenance_complete'
    | 'disposal';
  /**
   * Free-text note for the status-history row (trimmed; blank → null). Only meaningful alongside a `status` change.
   */
  changedNote?: string;
};

