export type ConnectedDeviceDto = {
  /**
   * Connected-device ID.
   */
  id: string;
  /**
   * Relay controller the device hangs off. Null for standalone devices.
   */
  relayControllerId: string | null;
  /**
   * Store the device is installed at.
   */
  storeId: string;
  /**
   * API-103 §4.1 (v0.5): store display name (joined). Null if the store row is missing.
   */
  storeName: string | null;
  /**
   * API-103 §4.1 (v0.5): relay-controller display name (joined). Null if unlinked.
   */
  relayControllerName: string | null;
  /**
   * Device name.
   */
  name: string;
  /**
   * Device kind. Constrains which `authMethod` values are accepted.
   */
  deviceType:
    | 'entry_gate'
    | 'exit_gate'
    | 'hydrogen_water'
    | 'body_composition'
    | 'tanning'
    | 'protein'
    | 'other'
    | 'gate_tablet'
    | 'area_door';
  /**
   * Serial number. Null when unrecorded.
   */
  serialNumber: string | null;
  /**
   * IP address. Null when the device is not IP-addressable.
   */
  ipAddress: string | null;
  /**
   * MAC address. Null when unrecorded.
   */
  macAddress: string | null;
  /**
   * Physical location note. Null when unset.
   */
  location: string | null;
  /**
   * API-103 §7.9: relay contact output, 1 to the controller's controlPortCount. Null only for authMethod=none (control-free auxiliary device).
   */
  outputPort: number | null;
  /**
   * The number on the device's member_scan QR sticker — the `minor=` of `…/unlock?major=<club code>&minor=<qrId>` (legacy `connected_device.qrId`, mobile board STT 125). Unique per store (E-DEV-015). Null = no sticker: the member app cannot start the device by scanning.
   */
  qrId: number | null;
  /**
   * gate_tablet only (E-02 261102_v3): 入館用 / 退館用. Null on other types.
   */
  tabletPurpose: 'entry' | 'exit';
  /**
   * gate_tablet only: the AWS IoT certificate id the tablet presents (mTLS). Null on other types.
   */
  certificateId: string | null;
  /**
   * gate_tablet only: the gate it unlocks (entry_gate for an entry tablet, exit_gate for an exit tablet). Null on other types.
   */
  linkedGateDeviceId: string | null;
  /**
   * area_door only (E-02 FR-003): the E-02 FR-016 area the door opens. Null on other types.
   */
  areaId: string | null;
  /**
   * area_door only: the area of `areaId`, resolved (name and 性別の条件 shown read-only). Null on other types, or when the area master could not be read.
   */
  area: ConnectedDeviceAreaDto | null;
  /**
   * Installation date (YYYY-MM-DD). Null when unset.
   */
  installedOn: string | null;
  /**
   * Device status. `discarded` rows are hidden from lists unless `includeDiscarded=true`.
   */
  status: 'normal' | 'abnormal' | 'under_maintenance' | 'discarded';
  /**
   * How the device authenticates a member. **`none` is only valid for `body_composition` and `other`** — any other type rejects it on write.
   */
  authMethod: 'member_scan' | 'device_scan' | 'none';
  /**
   * FR-008 usage-control: main-contract axis on/off.
   */
  isMainContractRequired: boolean;
  /**
   * FR-008 usage-control: permitted main-contract types, OR semantics — an active main contract of any one starts the device. `[]` = any type while the axis is on (always `[]` while it is off).
   */
  allowedContractTypes: Array<
    | 'general'
    | 'oneDay'
    | 'family'
    | 'kids'
    | 'student'
    | 'corporate'
    | 'welfare'
    | 'prepaid'
    | 'special'
  >;
  /**
   * Deprecated — read `allowedContractTypes`. The one type when exactly one is set; null otherwise (any type, axis off, or several types).
   *
   * @deprecated
   */
  allowedContractType: string | null;
  /**
   * FR-008 usage-control: permitted service types (option subcategories), OR semantics — holding any one starts the device. `[]` = service-type axis off. Replaces the single `allowedServiceType` (PO Q2).
   */
  allowedServiceTypes: Array<
    'protein' | 'supplement' | 'tanning' | 'collagen' | 'hydrogen_water' | 'body_planner' | 'shower'
  >;
  /**
   * Row creation timestamp (ISO 8601 UTC).
   */
  createdAt: string;
  /**
   * Last update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
};

