  /**
   * Target status. A device already in this status fails the batch (no-op transitions are rejected, 422 E-DEV-005).
   */
  newStatus: 'normal' | 'abnormal' | 'under_maintenance' | 'discarded';
  changedReason?:
    | 'install'
    | 'fault_report'
    | 'maintenance_start'
    | 'maintenance_complete'
    | 'disposal';
  /**
   * Written to every history row, trimmed. Omitted or blank → null.
   */
