export type BillingRunSummaryDto = {
  /**
   * Run id. Poll §6 GET /monthly-billing-runs/{runId} for progress.
   */
  runId: string;
  /**
   * Target billing month (YYYY-MM).
   */
  targetMonth: string;
  /**
   * PSP target (1 run = 1 method).
   */
  paymentMethod: 'sbps_credit' | 'jaccs_bank' | 'convenience_store';
  /**
   * Run lifecycle status. A fresh kick is `scheduled`.
   */
  status:
    | 'scheduled'
    | 'calculating'
    | 'calculated'
    | 'partially_confirmed'
    | 'fully_confirmed'
    | 'sent'
    | 'reconciled'
    | 'failed';
  /**
   * Re-run granularity.
   */
  targetScope: 'all_stores' | 'stores' | 'members';
  /**
   * Manual kick vs the scheduled (2-day) run.
   */
  triggeredBy: 'manual' | 'system';
  /**
   * Kick timestamp. Null until dispatched.
   */
  triggeredAt: string | null;
  /**
   * Calculation-finished timestamp. Null until the worker completes.
   */
  calculatedAt: string | null;
  /**
   * Billings created/updated by the run. Null until calculated.
   */
  calculatedBillingCount: number | null;
  /**
   * Total billed amount (tax-inclusive). Null until calculated.
   */
  calculatedTotalAmount: number | null;
  /**
   * Billings confirmed out of this run.
   */
  confirmedCount: number;
  /**
   * Billings still uncollected. Null until reconciled.
   */
  uncollectedCount: number | null;
  /**
   * True when the run recorded per-member calculation errors.
   */
  hasErrors: boolean;
  /**
   * Target stores (targetScope=stores; a per-store system run echoes its store). Null otherwise.
   */
  storeIds: Array<string> | null;
  /**
   * Target members (targetScope=members). Null otherwise.
   */
  memberIds: Array<string> | null;
  /**
   * Run row creation timestamp (ISO 8601).
   */
  createdAt: string;
  /**
   * Run row last-updated timestamp (ISO 8601).
   */
  updatedAt: string;
};

