export type TransactionRowDto = {
  /**
   * Source-table discriminator (derived in the UNION SELECT): `sale`=billing_items (+, a discount line −), `payment`=payments (+), `refund`=refund_application_lines (−), `write_off`=write_offs (−).
   */
  transactionType: 'sale' | 'payment' | 'refund' | 'write_off';
  /**
   * v0.7.3 §3.5 unique row key: `sale:{billingItemId}` / `refund:{refundApplicationLineId}` / `payment:{paymentId}` / `write_off:{writeOffId}`. Use it as the list row key; equal sort values are ordered by it (ascending).
   */
  rowKey: string;
  /**
   * PK of the PARENT source row (billing / payment / refund / write_off) — the EP #3 path key. v0.7.3: the lines of one billing / refund share it.
   */
  sourceId: string;
  /**
   * JST date. §3.3: sale=COALESCE(confirmed_at, created_at); payment=COALESCE(paid_at, failed_at, created_at); refund=COALESCE(refunded_at, created_at); write_off=document_date.
   */
  transactionDate: string;
  /**
   * Member the transaction belongs to.
   */
  memberId: string;
  /**
   * Member display name (`last first`), enriched from auth-svc. Null if the member row is gone or enrichment failed.
   */
  memberName: string | null;
  /**
   * `members.member_number` (human-readable member code), enriched from auth-svc. Null if unresolved.
   */
  memberCode: string | null;
  /**
   * Calculation store. Null only if the source row has no resolvable store.
   */
  storeId: string | null;
  /**
   * Store display name, enriched from contracts-svc. Null if the store row is gone or enrichment failed.
   */
  storeName: string | null;
  /**
   * Source billing header — sale=the line's billing (= sourceId); refund=the line's own `refund_application_lines.billing_id` (v0.7.3); payment=direct link, else the first allocation; write_off=write_offs.billing_id. Null when unresolved.
   */
  billingId: string | null;
  /**
   * v0.7.3 (replaces `billingItemIds[]`) — 請求明細ID of this row: sale=`billing_items.id`; refund=`refund_application_lines.billing_item_id` (may be null); payment / write_off=null.
   */
  billingItemId: string | null;
  /**
   * `billings.billing_type` when a billing is resolvable; null for payment/refund/write_off rows with no resolvable billing.
   */
  billingType:
    | 'monthly'
    | 'enrollment'
    | 'withdrawal'
    | 'per_use'
    | 'transfer'
    | 'manual'
    | 'carryover';
  /**
   * `billings.billing_month` (YYYY-MM). Null when no billing or a non-monthly billing.
   */
  billingMonth: string | null;
  /**
   * JPY, tax-exclusive, SIGNED. sale=the line's `amount_before_tax`; refund=−(refund_amount − refund_tax_amount) of the line; payment / write_off=amountIncludingTax − taxAmount.
   */
  amountExcludingTax: number;
  /**
   * Tax percent (10 / 8). sale=the line's `billing_items.tax_rate`; refund=the rate of the line's item (null when the line has no billingItemId); payment / write_off=the one rate of the items of their billing(s), null when mixed or none.
   */
  taxRate: 8 | 10;
  /**
   * JPY tax portion, SIGNED (§3.3 / §3.5). sale = the line's `tax_amount`; payment = Σ per-allocated-billing share (each billing's own tax ratio); refund = −the line's `refund_tax_amount`; write_off = the billing's ratio.
   */
  taxAmount: number;
  /**
   * JPY, tax-inclusive, SIGNED (BR-TXN-006): sale = the line's `amount_with_tax` (positive; a discount line negative — the sale rows of a billing sum to billings.total_amount); payment positive; refund = −the line's `refund_amount`; write_off negative (running-balance convention).
   */
  amountIncludingTax: number;
  /**
   * payment rows: `payments.payment_method`; refund rows: derived from `refunds.refund_method` (API-116 MD:253) — sbps_void / sbps_partial_refund → sbps_credit, jaccs_manual → jaccs_bank, cashpost / cash / bank_transfer → same name; sale / write_off (v0.7 BR-TXN-001 #12): the member's CURRENT primary method (financial_infos is_primary AND is_active AND not deleted), null when none. Values = DBML `payment_method`.
   */
  paymentMethod:
    | 'sbps_credit'
    | 'jaccs_bank'
    | 'cash'
    | 'card_onsite'
    | 'convenience_store'
    | 'sbps_link'
    | 'cashpost'
    | 'bank_transfer'
    | 'manual';
  /**
   * Unified BR-TXN-002 display status mapped from the source raw enums.
   */
  status:
    | 'pending'
    | 'confirmed'
    | 'unconfirmed'
    | 'cancelled'
    | 'refunded'
    | 'partial_refund'
    | 'written_off'
    | 'succeeded'
    | 'failed';
  /**
   * Source-table raw status snapshot (audit aid). Keys vary by transactionType: sale→{confirmStatus, collectionStatus}, payment→{paymentStatus}, refund→{refundStatus}, write_off→{writeOffStatus}.
   */
  rawStatus: RawStatusDto;
  /**
   * §4.4 / §7.1 BR-TXN-001 — derived per sale LINE lock-free (eventual-consistent; the detail EP re-validates under a NOWAIT lock). v0.7.3: `applicableAmount` = that line's remainder. Null for non-sale rows and when the line cannot be refunded (discount line, remainder 0, not refundable).
   */
  refundApplyContext: RefundApplyContextDto | null;
  /**
   * Source row `created_at` (ISO 8601).
   */
  createdAt: string;
  /**
   * Source row `updated_at` (ISO 8601).
   */
  updatedAt: string;
};

export type TransactionListResponseDto = {
  /**
   * v0.7.3 §3.5: one signed row per sale LINE, refund LINE, payment and write-off in the window, sorted by `sortBy`/`sortDir` (default transactionDate desc; ties → rowKey asc). Counts and paging count these rows.
   */
  items: Array<TransactionRowDto>;
  /**
   * `{ page, limit, totalItems, totalPages }`, plus `totalAllItems` only when `includeTotalAll=true`.
   */
  pagination: PaginationWithTotalAllDto;
};

export type LegacyTermFileDto = {
  /**
   * File label — the document title, or `terms` when it has none.
   */
  name: string;
  /**
   * PDF delivery URL (API-006) — the stored `public/terms/…` key on the public media origin, the same URL the CRM terms detail returns as `pdfUrl`. Readable without a token.
   */
  path: string;
};

export type LegacyTermResponseDto = {
  /**
   * Terms document **UUID** — send these back verbatim on accept.
   */
  id: string;
  /**
   * Y-04 terms_type.
   */
  type:
    | 'membership'
    | 'privacy'
    | 'payment'
    | 'suspension'
    | 'withdrawal'
    | 'companion'
    | 'account_terms'
    | 'digital_ticket';
  /**
   * Brands the document applies to. **`[]` when the request sent no `brand`** — it echoes the query rather than deriving the real applicability.
   */
  brands: Array<string>;
  /**
   * Document title. Null when unset.
   */
  name: string | null;
  /**
   * Viewer markup for `WebView.loadHtmlString` — the same document the by-type viewer serves: the stored `bodyText` (the CRM-extracted body, as a page) when the document has one, else **generated HTML** wrapping the stored PDF link. Null when the document has neither.
   */
  description: string | null;
  /**
   * Attached PDF, as a single-element array. `[]` when the document has no stored file.
   */
  files: Array<LegacyTermFileDto>;
  /**
   * Display label. Duplicates `name`.
   */
  label: string | null;
  /**
   * Whether the member has accepted it. Computed as the negation of "consent required now".
   */
  isAccept: boolean;
  /**
   * Whether to show the agree button — the exact negation of `isAccept`.
   */
  showAgreeButton: boolean;
};

export type RecordTermsConsentDto = {
  /**
   * Terms version IDs the member consents to (1–20).
   */
  termsIds: Array<string>;
  /**
   * Consent context (terms_consent_source).
   */
  source: 'revision_reaccept' | 'withdrawal_flow' | 'suspension_flow';
};

export type RecordConsentResponseDto = {
  /**
   * Newly-inserted consent rows. **Re-consenting to a version already accepted adds nothing**, so 0 can mean "all were already accepted" rather than a failure.
   */
  recorded: number;
};

export type EnrollmentPersonalInfoDto = {
  /**
   * In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  lastName?: string;
  /**
   * In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  firstName?: string;
  lastNameKana?: string;
  firstNameKana?: string;
  gender?: 'male' | 'female' | 'other' | 'prefer_not_to_say';
  /**
   * YYYY-MM-DD. In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  dateOfBirth?: string;
  /**
   * 7 digits, no hyphen. In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  postalCode?: string;
  /**
   * JIS X 0401 code ("13") or the prefecture name ("東京都") — both accepted, as on PATCH /members/me. In the required merged set. Send only if the stored member row does not already have it (server merges body over row). Note the legacy profile PATCH sends `addressId` instead, which is dropped — so a member who only went through the legacy profile screens still needs to supply this.
   */
  prefecture?: string;
  /**
   * In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  streetAddress?: string;
  building?: string;
  /**
   * In the required merged set — only the SMS-OTP signup lane caches a phone, so an email-OTP or social-login applicant must supply one here. Yamauchi-mastered: written only when the member has no phone cached yet; an existing value is kept (change it via the OTP flow).
   */
  phone?: string;
  /**
   * Yamauchi-mastered: written only when the member has no email cached yet (see `phone`).
   */
  email?: string;
  /**
   * Emergency contact last name (姓). In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  emergencyContactLastName?: string;
  /**
   * Emergency contact first name (名). In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  emergencyContactFirstName?: string;
  /**
   * Emergency contact phone — JP domestic, no hyphens. Hyphenated and `+81` input is normalised. In the required merged set. Send only if the stored member row does not already have it (server merges body over row).
   */
  emergencyContactPhone?: string;
  /**
   * API-006 face-photo S3 key. Body-only — the member row exposes a derived URL, not the key.
   */
  facePhotoS3Key?: string;
};

export type SelectedOptionDto = {
  /**
   * The option being contracted (`options.id`). For a locker this is the cabinet's fee option.
   */
  optionId?: string;
  /**
   * Option-set pick (`option_sets.id`). **Accepted, stored, and not yet expanded** into its member options — the set discount belongs to the API-145 pricing engine, so expanding it here would write full-price option contracts. Send the individual `optionId`s meanwhile.
   */
  optionSetId?: string;
  /**
   * The locker slot this option reserves (`locker_slots.id`). The slot is checked at submit and claimed inside the contract transaction, so it becomes `in_use` and is written back to `contracts.locker_slot_id`. At most one row in the array may carry one.
   */
  lockerSlotId?: string;
};

export type SubmitEnrollmentDto = {
  /**
   * PII **top-up** for the members row (§3.4.1). Omit entirely when the row is already complete — the applicant reached this call only by passing the profile gate (`GET /members/me/verify` reports `empty`/`noImage` until the profile and face photo exist), so name / DOB / address / emergency contact are normally already stored. The server merges each field over the stored row and checks completeness on the merged result: `422 E-ENR-001` when a required field is missing from both.
   */
  personalInfo?: EnrollmentPersonalInfoDto;
  planId: string;
  storeId: string;
  paymentMethod: 'sbps_credit' | 'jaccs_bank';
  /**
   * Accepted + stored; campaign validation/discount deferred (API-088/089).
   */
  campaignId?: string;
  /**
   * Promotion / family / referral code as typed by the member; resolved server-side (§3.4). Send this OR `promotionCodeId`.
   */
  promotionCode?: string;
  /**
   * Pre-resolved promotion-code id. Prefer `promotionCode` — the spec defines only the typed code.
   */
  promotionCodeId?: string;
  corporateId?: string;
  /**
   * OGF membership role — `owner` is the employee, `family` their household member. Accepted **only** alongside an `ogf_only` promotion code (the lane legacy keyed off a campaign code starting `OGF`); sent on any other lane the response is `400 E-VAL-001`. Requires `employeeCode`.
   */
  ogfType?: 'owner' | 'family';
  /**
   * 従業員番号. Required when `ogfType` is set. One member at a time may hold a given code as `owner` — a second one is `400 E-VAL-001` with `details: [{ field: "employeeCode", code: "duplicate" }]`; family members reuse the employee’s code freely.
   */
  employeeCode?: string;
  /**
   * Selected options, max 30. A bare option-id string is also accepted (legacy shape). A locker pick is an ordinary row carrying `lockerSlotId`; at most one row may carry one (two different slots → `400 E-VAL-001`).
   */
  selectedOptionIds?: Array<SelectedOptionDto>;
  /**
   * Accepted for compatibility and **ignored**: the initial charge is priced server-side from this body's `planId` / `selectedOptionIds` / `campaignId` (API-153 §5, the same computation as `GET /api/v1/sales/estimate-joining-fee`), and that is what is billed and recorded. A `totalInitial` that differs from the server price is logged, never used.
   */
  calculatedAmounts?: {
    [key: string]: unknown;
  };
  /**
   * JACCS contractor number (required for jaccs_bank).
   */
  jaccsContractorNumber?: string;
  /**
   * JACCS WebView callback status (only `completed` accepted for jaccs_bank).
   */
  jaccsCallbackStatus?: 'pending' | 'completed' | 'failed';
  /**
   * Plan usage start date (YYYY-MM-DD, today ≤ date ≤ today+2 months, JST). Same-day start is allowed.
   */
  usageStartDate: string;
  /**
   * Parental consent timestamp (ISO 8601), required when the applicant is a minor.
   */
  parentApprovalAt?: string;
  parentName?: string;
  /**
   * OPTIONAL (API-153 §3.4 marks it required — optional until the spec owner rules). `[{ termsDocumentId, consentedAt? }]`. When sent, each termsDocumentId must exist, be active, published today and require consent (else 400 E-VAL-001), and one terms_consents row (enrollment_app) is written per entry. Omitted or [] → no consent row; the app can keep recording consent through POST /api/v1/mobile/terms/consents (API-076 §10) or the legacy member-term/accept facade.
   */
  termsConsents?: Array<{
    [key: string]: unknown;
  }>;
};

export type EnrollmentMemberDto = {
  /**
   * The member.
   */
  memberId: string;
  /**
   * **Always `provisional` at this point.** Activation happens in a downstream batch (BAT-016), so a successful submit does not make the member active.
   */
  memberStatus: string;
};

export type EnrollmentNextStepDto = {
  /**
   * What happens next — e.g. staff review, or nothing further.
   */
  kind: string;
  /**
   * Ready-to-display Japanese message. **Null for kinds other than `under_review`** — render nothing rather than an empty string.
   */
  message: string | null;
};

export type EnrollmentSubmitResponseDto = {
  /**
   * Application ID.
   */
  applicationId: string;
  /**
   * A 10-digit human-readable receipt number, always exactly 10 digits.
   */
  applicationNumber: string;
  /**
   * Application state.
   */
  status: string;
  /**
   * How the application will be approved.
   */
  approvalMethod: string;
  /**
   * Submission timestamp.
   */
  submittedAt: string;
  /**
   * The member as of submission — `provisional`, not active.
   */
  member: EnrollmentMemberDto;
  /**
   * What the app should tell the applicant next.
   */
  nextStep: EnrollmentNextStepDto;
};

export type ApplicationListMemberDto = {
  /**
   * Member ID — the only field guaranteed present.
   */
  memberId: string;
  /**
   * Member number. **Absent when the member summary could not be loaded** (the object then carries `memberId` alone).
   */
  memberNumber?: string;
  /**
   * Family name. Absent when the summary could not be loaded.
   */
  lastName?: string | null;
  /**
   * Given name. Absent when the summary could not be loaded.
   */
  firstName?: string | null;
  /**
   * Family name in katakana. Absent when the summary could not be loaded.
   */
  lastNameKana?: string | null;
  /**
   * Given name in katakana. Absent when the summary could not be loaded.
   */
  firstNameKana?: string | null;
  /**
   * Date of birth. Absent when the summary could not be loaded.
   */
  dateOfBirth?: string | null;
  /**
   * Under 18 at the usage start date (FR-M004).
   */
  isMinor?: boolean;
};

export type ApplicationStoreRefDto = {
  storeId: string;
  code: string | null;
  name: string | null;
  brandEnum: string | null;
  brandGroup: 'JOYFIT' | 'FIT365';
};

export type ApplicationListCampaignRefDto = {
  campaignId: string;
  name: string | null;
};

export type ApplicationListPlanRefDto = {
  planId: string;
  name: string | null;
};

export type EnrollmentApplicationListItemDto = {
  /**
   * Application ID.
   */
  applicationId: string;
  /**
   * Human-readable application number.
   */
  applicationNumber: string;
  /**
   * Review status.
   */
  status: 'submitted' | 'under_review' | 'approved' | 'rejected' | 'cancelled';
  /**
   * How the application was approved (`manual` once approved). Null before approval.
   */
  approvalMethod: string | null;
  /**
   * Where the application came from (`mobile_app` / `crm_direct` / `proxy`).
   */
  applicationSource: string;
  /**
   * The linked promotion code has `scope_type=member_referral`.
   */
  hasReferralPromotionCode: boolean;
  /**
   * v1.19 FR-M001 入会経路, never null: `member_referral` code → `referral`; else `mobile_app` → `mobile`, `crm_direct` / `proxy` → `manual`.
   */
  enrollmentRoute: 'mobile' | 'manual' | 'referral';
  /**
   * The applicant. Degrades to `{ memberId }` when the summary lookup misses.
   */
  member: ApplicationListMemberDto;
  /**
   * Store applied to.
   */
  store: ApplicationStoreRefDto;
  /**
   * Null when no campaign applies.
   */
  campaign: ApplicationListCampaignRefDto | null;
  /**
   * Plan applied for.
   */
  plan: ApplicationListPlanRefDto;
  /**
   * Requested usage start date (YYYY-MM-DD). Null when unset.
   */
  usageStartDate: string | null;
  /**
   * Blacklist screen outcome. `unchecked` blocks the approval checklist.
   */
  blacklistMatchResult:
    | 'unchecked'
    | 'none'
    | 'name_dob'
    | 'email'
    | 'phone'
    | 'address'
    | 'multiple';
  /**
   * When the screen ran (ISO 8601 UTC). Null while `unchecked`.
   */
  blacklistMatchedAt: string | null;
  /**
   * When the application was filed (ISO 8601 UTC).
   */
  appliedAt: string;
  /**
   * v1.6 — the 「対応超過」 badge (C-01 FR-M001 L243). True when `status = submitted` and the row has been waiting longer than `reviewOverdueHours`. **Always false for any other status** — `under_review` means somebody has already started the review, so it is not 「未審査のまま」.
   */
  isReviewOverdue: boolean;
  /**
   * v1.6 — this row's brand threshold in hours (`stores.brand_enum → brands.review_overdue_hours`). Render the tooltip from this; never hard-code a threshold, and never compare `appliedAt` against the device clock. The value can differ per brand within one page.
   */
  reviewOverdueHours: number;
};

export type EnrollmentApplicationKpiDto = {
  /**
   * FR-M001 L242 「未審査件数」 — `COUNT(status = submitted)`. v1.6 corrected this: it counted `under_review`, which is the opposite of 未審査.
   */
  pendingReviewCount: number;
  /**
   * Applications whose blacklist screen returned a match.
   */
  blacklistFlaggedCount: number;
  /**
   * Supporting aggregate for the L243 alert — rows with `isReviewOverdue = true` in the caller’s role-scope baseline (v1.14 — not the filtered set), each measured against ITS OWN brand threshold. v1.6 corrected this too: it counted `under_review` rows against `updatedAt`.
   */
  overdueReviewCount: number;
};

export type EnrollmentApplicationListResponseDto = {
  /**
   * Applications on this page, scoped to the caller (HQ sees all, manager their stores, staff their own store).
   */
  items: Array<EnrollmentApplicationListItemDto>;
  /**
   * `totalAllItems` only when `includeTotalAll=true`.
   */
  pagination: PaginationWithTotalAllDto;
  /**
   * Queue-wide counters for the review screen — computed over the caller’s role-scope baseline (no filters, page or sort). v1.14: absent when `includeKpi=false`.
   */
  kpi?: EnrollmentApplicationKpiDto;
};

export type MaskedValueDto = {
  /**
   * **Always null.** The unmasked value is deliberately withheld.
   */
  value: string | null;
  /**
   * The masked rendering. Null when the source field is empty.
   */
  masked: string | null;
};

export type MaskedAddressDto = {
  /**
   * **Always null** — withheld.
   */
  postalCode: string | null;
  /**
   * **Always null** — withheld.
   */
  prefectureCode: string | null;
  /**
   * **Always null** — withheld.
   */
  streetAddress: string | null;
  /**
   * **Always null** — withheld.
   */
  building: string | null;
  /**
   * The masked rendering — prefecture plus a mask. Null when no prefecture is stored.
   */
  masked: string | null;
};

export type ApplicationDetailMemberDto = {
  /**
   * Member ID.
   */
  memberId: string;
  /**
   * Member number.
   */
  memberNumber: string;
  /**
   * §4.3 v1.7 — Yamauchi API `User.id` (integer). Null until the account is linked.
   */
  yamauchiUserId: number | null;
  /**
   * Current member type.
   */
  memberType: string;
  /**
   * Current member status.
   */
  memberStatus: string;
  /**
   * Member type before this application — the value a cancel rolls back to.
   */
  originalMemberType: string;
  /**
   * Family name. Null when unset.
   */
  lastName: string | null;
  /**
   * Given name. Null when unset.
   */
  firstName: string | null;
  /**
   * Family name in katakana. Null when unset.
   */
  lastNameKana: string | null;
  /**
   * Given name in katakana. Null when unset.
   */
  firstNameKana: string | null;
  /**
   * Date of birth. Null when unset.
   */
  dateOfBirth: string | null;
  /**
   * §4.3 — renamed from `sex` in v1.3, matching the request field and `members.gender`. Null when unset.
   */
  gender: 'male' | 'female' | 'other' | 'prefer_not_to_say';
  /**
   * §4.3 — age computed from `dateOfBirth` at the application `createdAt` (JST).
   */
  ageAtApplication: number;
  /**
   * Under 18 at the usage start date (FR-M004).
   */
  isMinor: boolean;
  /**
   * Phone, masked. `value` always null.
   */
  phoneNumber: MaskedValueDto;
  /**
   * Email, masked. `value` always null.
   */
  email: MaskedValueDto;
  /**
   * Address, masked. Every component is null except `masked`.
   */
  address: MaskedAddressDto;
  /**
   * Asset URL; the BFF authorizes the staff reader and redirects to a short-lived signed URL. Null when no photo.
   */
  facePhotoSignedUrl: string | null;
  /**
   * members.face_photo_updated_at — null = unknown (photo stored before the column existed).
   */
  facePhotoRegisteredAt: string | null;
  /**
   * §4.3 v1.5 — previous withdrawal date, snapshotted at application (from the 6a snapshot, not the live member row). Null when no previous withdrawal.
   */
  previousWithdrawalDate: string | null;
  /**
   * When a guardian approved (ISO 8601 UTC). Null for adults.
   */
  parentApprovalAt: string | null;
  /**
   * Guardian name. Null for adults.
   */
  parentName: string | null;
};

