export type ApplicationCalculatedAmountsDto = {
  /**
   * JOYFIT 入会金 (tax-included, API-098 v1.11 §4.3); null for FIT365. Amounts are the stored snapshot — snapshots written before API-074 v0.8 hold tax-excluded values.
   */
  enrollmentFee: number | null;
  /**
   * Waiver / discount on the enrollment fee, any type. 0 = none.
   */
  enrollmentFeeDiscount: number;
  registrationFee: number | null;
  cardIssueFee: number | null;
  /**
   * FIT365 annual fee; not part of totalInitial.
   */
  maintenanceFee: number | null;
  /**
   * `plans.prepaid_months` (N). The usage-start month is month 1 (API-098 v1.17 §4.3).
   */
  prepaidMonths: number | null;
  /**
   * Plan months 1..N in the first charge (tax-included) = firstMonthProratedFee + monthly × (N − 1), each month an integer.
   */
  prepaidTotal: number | null;
  /**
   * Month-1 plan fee = floor(ceil(ceil(price × 100 / (100 + tax)) × D / L) × (100 + tax) / 100), price = the stored 税込 master (API-098 v1.22 §4.3); a start on the 1st is the full month.
   */
  firstMonthProratedFee: number | null;
  /**
   * Month-2 plan fee (full month, tax-included). Null when N = 1.
   */
  nextMonthFee: number | null;
  /**
   * Options, month 1 only (tax-included; prorated when the option prorates; per-use options excluded). 0 = no options.
   */
  optionMonthlyTotal: number | null;
  /**
   * Plan campaign discount in month 1 (positive, tax-included, prorated). Null when off or outside the apply window.
   */
  campaignDiscountMonth1: number | null;
  /**
   * Plan campaign discount in month 2 (positive, tax-included). Null when off, outside the apply window, or N = 1.
   */
  campaignDiscountMonth2: number | null;
  /**
   * Plan campaign discount for months 3..N together (positive, tax-included) — only on a plan prepaid 3 months or more, for the months inside the apply window. Null when none, or on an application recorded before months 3+ were discounted.
   */
  campaignDiscountLaterMonths: number | null;
  /**
   * API-098 v1.17: option campaign discounts in the first charge (month 1 only, positive, tax-included). Null when none.
   */
  campaignOptionDiscountTotal: number | null;
  /**
   * Render as returned — never re-sum the lines (TBD-C01-TOTAL-INITIAL-COMPOSITION).
   */
  totalInitial: number | null;
  firstBillingDate: string | null;
  jaccsCombinedWithNextMonth: boolean | null;
};

