export type ApplicationTimelineItemDto = {
  /**
   * Discriminator. `event` rows carry `historyId`/`fromStatus`/`toStatus`/`comment`; `memo` rows carry `memoId`/`memo`/`canDelete`.
   */
  type: 'event' | 'memo';
  /**
   * When it happened (ISO 8601 UTC) — the single sort key across both kinds.
   */
  occurredAt: string;
  /**
   * Who acted. Null for member / system events.
   */
  actor: ApplicationStaffRefDto | null;
  /**
   * `event` rows only — the status-history row ID.
   */
  historyId?: string;
  /**
   * `event` rows only — status before the transition. Null for the first entry.
   */
  fromStatus?: string | null;
  /**
   * `event` rows only — status after the transition.
   */
  toStatus?: string;
  /**
   * `event` rows only — comment pulled out of the history metadata.
   */
  comment?: string | null;
  /**
   * `event` rows only — the reject reason on a `toStatus=rejected` row; null on every other transition. Same value as the top-level `rejectReasonCode` for the latest rejection.
   */
  rejectReasonCode?:
    | 'identity_verification_failure'
    | 'age_restriction'
    | 'blacklist_match'
    | 'other';
  /**
   * `memo` rows only — the memo ID.
   */
  memoId?: string;
  /**
   * `memo` rows only — the memo text.
   */
  memo?: string;
  /**
   * `memo` rows only — whether **this caller** may delete it (own memo, or the `can_delete_others_application_memo` permission). Caller-dependent, so it differs per requester.
   */
  canDelete?: boolean;
};

export type EnrollmentApplicationDetailDto = {
  /**
   * Application ID.
   */
  applicationId: string;
  /**
   * Human-readable application number.
   */
  applicationNumber: string;
  /**
   * Review status.
   */
  status: 'submitted' | 'under_review' | 'approved' | 'rejected' | 'cancelled';
  /**
   * How the application was approved. Null before approval.
   */
  approvalMethod: string | null;
  /**
   * Where the application came from.
   */
  applicationSource: string;
  /**
   * The linked promotion code has `scope_type=member_referral`.
   */
  hasReferralPromotionCode: boolean;
  /**
   * v1.19 FR-M001 入会経路, never null: `member_referral` code → `referral`; else `mobile_app` → `mobile`, `crm_direct` / `proxy` → `manual`. The detail screen still shows the 2-value `applicationSource` (FR-M002).
   */
  enrollmentRoute: 'mobile' | 'manual' | 'referral';
  /**
   * The applicant with **masked** PII. Degrades to `{ memberId }` when the summary lookup misses.
   */
  member: ApplicationDetailMemberDto;
  /**
   * Store applied to.
   */
  store: ApplicationStoreRefDto;
  /**
   * Null when none.
   */
  campaign: ApplicationCampaignRefDto | null;
  /**
   * Plan applied for.
   */
  plan: ApplicationDetailPlanDto;
  /**
   * Chosen options. Empty when none.
   */
  selectedOptions: Array<ApplicationOptionDto>;
  /**
   * Null when none.
   */
  promotionCode: ApplicationPromotionCodeDto | null;
  /**
   * Corporate contract as `{ corporateId, billingPattern }`. Null for individual applications.
   */
  corporate: {
    [key: string]: unknown;
  } | null;
  /**
   * Billing pattern. Null when unset.
   */
  billingPattern: string | null;
  /**
   * Requested usage start date (YYYY-MM-DD). Null when unset.
   */
  usageStartDate: string | null;
  /**
   * Chosen payment method. Null when unset.
   */
  paymentMethod: string | null;
  /**
   * §4.3 — the 17 keys from the application-time snapshot.
   */
  calculatedAmounts: ApplicationCalculatedAmountsDto;
  /**
   * v1.5 enrollment-fee waiver: `{ type: campaign|reenrollment|staff, reason, appliedAt, appliedBy }`. **Null = no waiver.** `reason`/`appliedBy` are non-null only for `staff`. Show the 「個別に免除する」 affordance only when status is submitted/under_review AND this is null AND `calculatedAmounts.enrollmentFee > 0`.
   */
  enrollmentFeeWaiver: {
    [key: string]: unknown;
  } | null;
  /**
   * v1.5 re-enrollment waiver rule state: `{ ruleDays, eligible, daysSinceWithdrawal, excludedReason }`, derived on read. **Null = the brand has no rule** → hide the 「再入会免除規則」 row entirely. Render `ruleDays`; never hard-code a day count.
   */
  reenrollmentWaiver: {
    [key: string]: unknown;
  } | null;
  /**
   * v1.7 — same-day cancel count of the applicant member (every status, 0 included). Same counter as the §8 cancel guard.
   */
  sameDayCancelCount: number;
  /**
   * v1.7 — same-day cancel limit. Render 「当日取り消し回数 n / limit」 from these two fields; do not hard-code the 2.
   */
  sameDayCancelLimit: number;
  /**
   * Blacklist screen state. `matchedRecords` is always empty here.
   */
  blacklist: ApplicationBlacklistDto;
  /**
   * **Null exactly when `applicationSource` is `mobile_app`.**
   */
  proxy: ApplicationProxyInfoDto | null;
  /**
   * The contract created on approval; null until approved.
   */
  contract: ApplicationContractRefDto | null;
  /**
   * Derived pre-approval checks. `ageEligible` is a placeholder — see the DTO.
   */
  approvalChecklist: ApplicationApprovalChecklistDto;
  /**
   * Status events and memos merged and sorted ascending by `occurredAt`. Read `type` before reading the other fields.
   */
  timeline: Array<ApplicationTimelineItemDto>;
  /**
   * When the application was filed (ISO 8601 UTC).
   */
  appliedAt: string;
  /**
   * When the status last changed. Falls back to `appliedAt` when there is no history yet.
   */
  lastStatusChangeAt: string;
  /**
   * Latest to_status=approved history row. Same rule for the fields below.
   */
  approvedAt: string | null;
  approvedBy: ApplicationStaffRefDto | null;
  rejectedAt: string | null;
  rejectedBy: ApplicationStaffRefDto | null;
  rejectReasonCode:
    | 'identity_verification_failure'
    | 'age_restriction'
    | 'blacklist_match'
    | 'other';
  cancelledAt: string | null;
  cancelledBy: ApplicationStaffRefDto | null;
  cancelReason: string | null;
};

