export type TermsDocumentSummaryDto = {
  /**
   * Terms document ID.
   */
  id: string;
  /**
   * The **original** document this row is a version of — the anchor for the whole group. Null when this row IS the original.
   */
  parentTermsId: string | null;
  /**
   * Document type. Inherited from the source on version create, never client-supplied.
   */
  termsType:
    | 'membership'
    | 'privacy'
    | 'payment'
    | 'suspension'
    | 'withdrawal'
    | 'companion'
    | 'account_terms'
    | 'digital_ticket';
  /**
   * Brand GROUP the document applies to (JOYFIT | FIT365). Null for company-wide terms. A non-HQ caller cannot filter beyond their own brand group(s).
   */
  brandEnum: string | null;
  /**
   * Document title.
   */
  title: string;
  /**
   * Version label.
   */
  version: string;
  /**
   * First day the version is in force (YYYY-MM-DD).
   */
  effectiveFrom: string;
  /**
   * Last day in force (YYYY-MM-DD). Null while open-ended — creating a newer version sets this to `newEffectiveFrom − 1 day`.
   */
  effectiveTo: string | null;
  /**
   * Whether members must consent to this document.
   */
  requiresConsent: boolean;
  /**
   * Publication status, **derived** from the effective window in JST (inclusive both ends) — never a stored column: `draft` 下書き (effectiveFrom is in the future), `published` 公開中 (today is within the window, or it is open-ended), `ended` 適用終了 (effectiveTo has passed — always because a newer version closed it). Filterable via `?status=`, which is applied as a time predicate in SQL so pagination and `total` agree with the labels.
   */
  status: 'draft' | 'published' | 'ended';
  /**
   * Derived from `deletedAt` — the summary exposes a boolean, the detail exposes the timestamp.
   */
  isDeleted: boolean;
  /**
   * Display order within its type.
   */
  displayOrder: number;
};

export type TermsPaginationDto = {
  /**
   * Current page number (1-based).
   */
  page: number;
  /**
   * Page size applied.
   */
  limit: number;
  /**
   * Total matching rows. **Named `total`, not `totalItems`.**
   */
  total: number;
  /**
   * Total pages — `ceil(total / limit)`, so **0 when there are no results** (unlike the rest of the API, which floors at 1).
   */
  totalPages: number;
  /**
   * Baseline count for 「全 N 件中」: rows of the requested `termsType` tab, brand scope kept, every other filter reset — live rows only, plus logically-deleted rows when `includeDeleted=true`. Present only when `includeTotalAll=true`; `total <= totalAllItems`.
   */
  totalAllItems?: number;
};

export type TermsDocumentListResponseDto = {
  /**
   * Documents on this page, scoped to the caller’s brand set.
   */
  items: Array<TermsDocumentSummaryDto>;
  /**
   * The API-076-specific envelope — see `TermsPaginationDto`.
   */
  pagination: TermsPaginationDto;
};

export type TermsBrandScopeDto = {
  /**
   * Brand GROUPS the caller may read (§11.5) — the same set every list/detail read is scoped to (shared `brandEnum: null` documents are always readable on top). **null** = unrestricted (system / headquarter). An empty array means a scoped role whose stores resolve to no group (it then reads shared documents only).
   */
  brandGroups: Array<'JOYFIT' | 'FIT365'> | null;
};

export type TermsRelatedVersionDto = {
  /**
   * Sibling version ID.
   */
  id: string;
  /**
   * Version label.
   */
  version: string;
  /**
   * First day in force (YYYY-MM-DD).
   */
  effectiveFrom: string;
  /**
   * Last day in force (YYYY-MM-DD). Null while open-ended.
   */
  effectiveTo: string | null;
  /**
   * That version’s remarks (change note). Null when none.
   */
  remarks: string | null;
  /**
   * That version’s derived status, evaluated at the **same instant** as the parent row’s, so the group reads as one consistent timeline.
   */
  status: 'draft' | 'published' | 'ended';
  /**
   * Whether that version is logically deleted.
   */
  isDeleted: boolean;
};

export type TermsDocumentDetailDto = {
  /**
   * Terms document ID.
   */
  id: string;
  /**
   * The **original** document — the version-group anchor. Null when this row is the original.
   */
  parentTermsId: string | null;
  /**
   * The **immediate predecessor** version. Distinct from `parentTermsId`: parent is the original, prev is the one directly before this (§11.3). Null for the first version.
   */
  prevTermsId: string | null;
  /**
   * Document type.
   */
  termsType:
    | 'membership'
    | 'privacy'
    | 'payment'
    | 'suspension'
    | 'withdrawal'
    | 'companion'
    | 'account_terms'
    | 'digital_ticket';
  /**
   * Brand GROUP the document applies to (JOYFIT | FIT365). Null for company-wide terms.
   */
  brandEnum: string | null;
  /**
   * Document title.
   */
  title: string;
  /**
   * Version label.
   */
  version: string;
  /**
   * Raw S3 key of the PDF (the column is `contentS3Key`). Null when no file is attached.
   */
  pdfS3Key: string | null;
  /**
   * Delivery URL of the PDF, resolved from `pdfS3Key` (API-006, §11.4) — openable as is. Null when no file is attached.
   */
  pdfUrl: string | null;
  /**
   * Original PDF file name for the 規約本文 card (API-076 v0.8 §4.3). **Derive-on-read** from `upload_sessions.file_name` by `s3_key` — never stored on `terms_documents`. Null when the upload session cannot be resolved (no PDF attached, unknown key, or media-svc unreachable) — render a placeholder rather than treating null as an error.
   */
  pdfFileName: string | null;
  /**
   * PDF file size in **bytes** (§4.3) — the UI formats KB/MB. Derive-on-read from `upload_sessions.file_size`; null in the same cases as `pdfFileName`.
   */
  pdfFileSize: number | null;
  /**
   * Terms body text for the 規約本文 card’s scroll view (API-076 v0.8 §4.3, method D / GAP-59). Extracted from the PDF **by the frontend** at upload time and stored verbatim — the backend never parses the PDF and never checks the text against it, so the PDF remains the legal master. Non-nullable: a document created before v0.8 has no extracted text and reads as an empty string, not null.
   */
  bodyText: string;
  /**
   * First day in force (YYYY-MM-DD).
   */
  effectiveFrom: string;
  /**
   * Last day in force (YYYY-MM-DD). Null while open-ended.
   */
  effectiveTo: string | null;
  /**
   * Display order within its type.
   */
  displayOrder: number;
  /**
   * Whether members must consent to this document.
   */
  requiresConsent: boolean;
  /**
   * Internal remarks. Null when unset.
   */
  remarks: string | null;
  /**
   * Publication status, **derived** from the effective window in JST (inclusive both ends) — never a stored column: `draft` 下書き (effectiveFrom is in the future), `published` 公開中 (today is within the window, or it is open-ended), `ended` 適用終了 (effectiveTo has passed — always because a newer version closed it). Filterable via `?status=`, which is applied as a time predicate in SQL so pagination and `total` agree with the labels.
   */
  status: 'draft' | 'published' | 'ended';
  /**
   * Every version in this group, anchored on the original — **including this row itself** and any logically-deleted siblings.
   */
  relatedVersions: Array<TermsRelatedVersionDto>;
  /**
   * Staff ID that created the row. Null for seeded documents.
   */
  createdBy: string | null;
  /**
   * 作成者 display name for `createdBy` (§4.3, the id+name pair ruling of 2026-08-25) — `<last_name> <first_name>`, resolved from the auth-svc-owned `staffs` through one batched directory call. **Not** filtered by `deleted_at`: an audit trail must still name who acted after that person leaves. Null when there is no `createdBy`, when the id is unknown to the directory, or when the lookup fails — a name lookup never fails the read.
   */
  createdByName: string | null;
  /**
   * Staff ID of the last update. Null when never updated.
   */
  updatedBy: string | null;
  /**
   * 最終更新者 display name for `updatedBy` (§4.3) — the column the CRM detail header renders instead of a raw UUID. Resolved in the same batched call as `createdByName`. **Non-nullable, matching the mirror**: an absent `updatedBy`, an unknown id, or a directory transport failure all degrade to an empty string, never null.
   */
  updatedByName: string;
  /**
   * Row creation timestamp (ISO 8601 UTC).
   */
  createdAt: string;
  /**
   * Last update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
  /**
   * Logical-delete timestamp. The detail exposes the timestamp where the list projection exposes the `isDeleted` boolean.
   */
  deletedAt: string | null;
};

export type CreateTermsDto = {
  /**
   * Edit-locked after create (§11.2).
   */
  termsType:
    | 'membership'
    | 'privacy'
    | 'payment'
    | 'suspension'
    | 'withdrawal'
    | 'companion'
    | 'account_terms'
    | 'digital_ticket';
  /**
   * Edit-locked after create (§11.2). `null` = one shared document that applies to both brand groups.
   */
  brandEnum: 'JOYFIT' | 'FIT365' | null;
  title: string;
  version: string;
  /**
   * S3 key of the PDF uploaded via API-006 (tag=terms, ≤100MB, application/pdf).
   */
  pdfS3Key: string;
  /**
   * Terms body text, extracted from the PDF **by the client** at upload time (method D — the server does not parse the PDF). Stored to `terms_documents.body_text` and served back by §4.3 `bodyText` for the 規約本文 card. Either plain text or the markup fragment `<div data-font="serif|sans"><p style="…">…</p>…</div>` (only `<p>` blocks; `style` limited to margin-left / margin-top / text-indent / font-size in `em`, font-weight:bold and text-align:right); any other markup is rejected as `400 E-VAL-001`. The 75,000,000-character cap is an API-layer payload guard sized so the full text of any PDF ≤10MB fits (no truncation); the column itself is unbounded `text`. A request body over the terms route's 80MB JSON limit is rejected as `400 E-VAL-001` (`body` `too_large`).
   */
  bodyText: string;
  /**
   * YYYY-MM-DD.
   */
  effectiveFrom: string;
  /**
   * null = open-ended. Must be >= effectiveFrom (E-TERM-002).
   */
  effectiveTo?: string | null;
  displayOrder?: number | null;
  requiresConsent?: boolean;
  remarks?: string | null;
};

export type UpdateTermsDto = {
  title?: string;
  version?: string;
  /**
   * New PDF S3 key (API-006). **Requires `bodyText` in the same request** — see `bodyText`.
   */
  pdfS3Key?: string;
  /**
   * Terms body text, extracted from the PDF **by the client** at upload time (method D — the server does not parse the PDF). Stored to `terms_documents.body_text` and served back by §4.3 `bodyText` for the 規約本文 card. Either plain text or the markup fragment `<div data-font="serif|sans"><p style="…">…</p>…</div>` (only `<p>` blocks; `style` limited to margin-left / margin-top / text-indent / font-size in `em`, font-weight:bold and text-align:right); any other markup is rejected as `400 E-VAL-001`. The 75,000,000-character cap is an API-layer payload guard sized so the full text of any PDF ≤10MB fits (no truncation); the column itself is unbounded `text`. A request body over the terms route's 80MB JSON limit is rejected as `400 E-VAL-001` (`body` `too_large`). **§6.2 PDF/text pairing rule (one-directional)**: sending `pdfS3Key` without `bodyText` is `400 E-VAL-001` — a new PDF must bring its re-extracted text. Sending `bodyText` alone is allowed, for a typo fix in the extracted text; no consistency check is run against the stored PDF.
   */
  bodyText?: string;
  effectiveFrom?: string;
  effectiveTo?: string | null;
  displayOrder?: number | null;
  requiresConsent?: boolean;
  remarks?: string | null;
};

export type CreateTermsVersionDto = {
  title: string;
  version: string;
  /**
   * S3 key of the new version's PDF (API-006).
   */
  pdfS3Key: string;
  /**
   * Terms body text, extracted from the PDF **by the client** at upload time (method D — the server does not parse the PDF). Stored to `terms_documents.body_text` and served back by §4.3 `bodyText` for the 規約本文 card. Either plain text or the markup fragment `<div data-font="serif|sans"><p style="…">…</p>…</div>` (only `<p>` blocks; `style` limited to margin-left / margin-top / text-indent / font-size in `em`, font-weight:bold and text-align:right); any other markup is rejected as `400 E-VAL-001`. The 75,000,000-character cap is an API-layer payload guard sized so the full text of any PDF ≤10MB fits (no truncation); the column itself is unbounded `text`. A request body over the terms route's 80MB JSON limit is rejected as `400 E-VAL-001` (`body` `too_large`). Required on a new version (§8.2): the revised PDF must bring its own text. It is **never inherited from the source version** — falling back would pair the new PDF with the previous document’s body.
   */
  bodyText: string;
  /**
   * The prior version is auto-closed to this date − 1 day (§11.3).
   */
  effectiveFrom: string;
  effectiveTo?: string | null;
  displayOrder?: number | null;
  requiresConsent?: boolean;
  remarks?: string | null;
};

