export type LockerListItemDto = {
  /**
   * Cabinet ID — internal key for navigation / PATCH, not a display value (§4.1 v0.14). The CRM shows `locationCode`.
   */
  id: string;
  /**
   * Store the cabinet stands in.
   */
  storeId: string;
  /**
   * Store code (`stores.code`). Show it with `locationCode` in an HQ all-stores list, where location codes repeat across stores.
   */
  storeCode: string;
  /**
   * Store name (`stores.name`).
   */
  storeName: string;
  /**
   * Locker-location master ID.
   */
  lockerLocationId: string;
  /**
   * Location code (A–Z) joined from the master — the cabinet's display identity (「ロッカーID」 column), unique in a store and the default sort key.
   */
  locationCode: string;
  /**
   * Location display name joined from the master.
   */
  locationName: string;
  /**
   * Cabinet shape. Always 3 columns; the name gives the row count.
   */
  shapeType: 'three_by_nine' | 'three_by_seven' | 'three_by_five' | 'three_by_two';
  /**
   * Floor-map X coordinate (Y-02 FR-006): relative 0.0–1.0 from the floor-plan image's top-left origin. Null when not placed — always null together with mapY.
   */
  mapX: number | null;
  /**
   * Floor-map Y coordinate, same basis as mapX. Null when unplaced.
   */
  mapY: number | null;
  /**
   * Total live slots (derived, `deleted_at IS NULL`).
   */
  slotCount: number;
  /**
   * `available` slot count (derived). The `sort=availableSlotCount` axis orders on this same figure.
   */
  availableSlotCount: number;
  /**
   * `in_use` slot count (derived).
   */
  inUseSlotCount: number;
  /**
   * `pending_release` slot count (derived).
   */
  pendingReleaseSlotCount: number;
  /**
   * Whether the cabinet is in service.
   */
  isActive: boolean;
  /**
   * True when the cabinet has at least one non-deleted image.
   */
  hasImages: boolean;
  /**
   * Normal-row fee option (same as the detail). Null when the cabinet carries no option.
   */
  optionId: string | null;
  /**
   * Contract-form (fee option) name joined from the cabinet's optionId. Null when the cabinet carries no option.
   */
  optionName: string | null;
  /**
   * Contract-form code (`options.option_code`, OP-0001 format) of the same option. Null when the cabinet carries no option.
   */
  optionCode: string | null;
  /**
   * Bottom-row fee option (FR-013, same as the detail). Null when unset.
   */
  bottomOptionId: string | null;
  /**
   * Name of bottomOptionId. Null when unset.
   */
  bottomOptionName: string | null;
  /**
   * Code of bottomOptionId (OP-0001 format). Null when unset.
   */
  bottomOptionCode: string | null;
  /**
   * Numbering pattern (FR-003) — for the 「ナンバリングパターン」 column.
   */
  orderType:
    | 'top_left_to_top_right'
    | 'top_right_to_top_left'
    | 'top_left_to_bottom_left'
    | 'top_right_to_bottom_right';
  /**
   * Starting slot number. The CRM composes the displayed range (e.g. `B-001〜B-021`) from locationCode + slotStartNumber + slotCount.
   */
  slotStartNumber: number;
  /**
   * Last update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
};

