export type AdminLockerSlotDto = {
  /**
   * Slot ID.
   */
  id: string;
  /**
   * Parent cabinet.
   */
  lockerId: string;
  /**
   * Owning store (joined through the cabinet).
   */
  storeId: string;
  /**
   * Slot number, zero-padded to 3 digits (rows made before that may be unpadded).
   */
  slotCode: string;
  /**
   * Zero-based row index.
   */
  rowIndex: number;
  /**
   * Zero-based column index (0–2).
   */
  columnIndex: number;
  /**
   * Slot status (transitions belong to API-101).
   */
  status: 'available' | 'in_use' | 'pending_release';
  /**
   * Lock method. Cannot be changed while `status` is `in_use` (E-LOC-006).
   */
  lockMethod: 'key_lock' | 'dial_lock' | 'padlock' | 'ic_lock';
  /**
   * How the slot is opened.
   */
  openMethod: 'door' | 'drawer';
  /**
   * Four-digit dial PIN (FR-009). **Null unless `lockMethod` is `dial_lock`.** Visible to every read role.
   */
  pinCode: string | null;
  /**
   * When the PIN last changed (ISO 8601 UTC). **Null unless `lockMethod` is `dial_lock`**, or when never set.
   */
  pinUpdatedAt: string | null;
  /**
   * Slot width in cm.
   */
  sizeWCm: number;
  /**
   * Slot height in cm.
   */
  sizeHCm: number;
  /**
   * Slot depth in cm.
   */
  sizeDCm: number;
  /**
   * Bottom-row flag (FR-013).
   */
  isBottomRow: boolean;
  /**
   * Per-slot fee-option override. Null = cabinet default. Read-only here; the slot PATCH rejects it (written by API-101 PUT …/fee-option).
   */
  feeOptionId: string | null;
  /**
   * Cleaning-completed timestamp (FR-007, ISO 8601 UTC), set by API-101 on pending_release → available. Null when not cleaned.
   */
  cleanedAt: string | null;
  /**
   * Created timestamp (ISO 8601 UTC).
   */
  createdAt: string;
  /**
   * Last update timestamp (ISO 8601 UTC). Send it back as `expectedUpdatedAt` on PATCH.
   */
  updatedAt: string;
};

export type UpdateLockerSlotDto = {
  /**
   * Blocked with E-LOC-006 while the slot is in use. Leaving dial_lock clears the PIN.
   */
  lockMethod?: 'key_lock' | 'dial_lock' | 'padlock' | 'ic_lock';
  openMethod?: 'door' | 'drawer';
  /**
   * 4 numeric digits; dial-lock slots only. A PIN on a non-dial slot, or not 4 digits, is 422 E-LOC-007. null clears it.
   */
  pinCode?: string | null;
  sizeWCm?: number;
  sizeHCm?: number;
  sizeDCm?: number;
  /**
   * Marks the slot as bottom-row: without a feeOptionId it bills the cabinet's bottomOptionId, else optionId (API-100 v0.16). A feeOptionId override does not block a change (§6.2 #5).
   */
  isBottomRow?: boolean;
  /**
   * Optimistic lock against the slot's current updatedAt (stale → 422 E-LOC-006).
   */
  expectedUpdatedAt?: string;
};

