export type PlanListItemDto = {
  /**
   * Plan master ID.
   */
  planId: string;
  /**
   * Human-readable plan code (FR-M001 主契約ID) — auto-numbered, unique, immutable.
   */
  planCode: string;
  /**
   * Brand the plan belongs to.
   */
  brandEnum: string;
  /**
   * Contract type. Drives which of `storeId` / `corporateId` must be set.
   */
  contractType:
    | 'general'
    | 'oneDay'
    | 'family'
    | 'kids'
    | 'student'
    | 'corporate'
    | 'welfare'
    | 'prepaid'
    | 'special';
  /**
   * Internal plan name.
   */
  name: string;
  /**
   * Member-facing plan name. Null when unset.
   */
  nameForMember: string | null;
  /**
   * Store the plan is limited to. Non-null only for `special`.
   */
  storeId: string | null;
  /**
   * Store name projection (FR-M001 店舗列). Null when `storeId` is null.
   */
  storeName: string | null;
  /**
   * Monthly price in JPY, **tax-inclusive** as stored (API-087 v0.14).
   */
  priceMonthly: number;
  /**
   * Tax rate in percent applied to the monthly price.
   */
  taxRate: number;
  /**
   * Whether the plan grants the companion benefit.
   */
  hasCompanionBenefit: boolean;
  /**
   * Whether the plan is currently sellable.
   */
  isActive: boolean;
  /**
   * FR-M005 copy guard — false disables the copy action (E-PLN-004).
   */
  isCopyable: boolean;
  /**
   * Parent plan when this row is a derived plan. Null for root plans.
   */
  parentPlanId: string | null;
  /**
   * Parent plan name (FR-M001 親主契約列). Returned even when the parent is soft-deleted. Null for root plans.
   */
  parentPlanName: string | null;
  /**
   * Number of active member contracts on this plan. Zero is the precondition for edit/delete.
   */
  contractCount: number;
  /**
   * 利用できるエリア (G-01 FR-M002) — E-02 FR-016 area ids; `[]` = none.
   */
  areaIds: Array<string>;
  /**
   * Who this may be sold / granted to (E-02 FR-016, G-01 FR-M002, G-02 FR-002): `none` = everyone; `female_only` / `male_only` = only members whose gender is `female` / `male` (other, prefer_not_to_say and unset do not qualify); `nobody` = the conditions contradict each other. Derived from the areas' gender conditions (and, for a plan, `limitOfSex`).
   */
  genderCondition: 'none' | 'female_only' | 'male_only' | 'nobody';
  /**
   * Row creation timestamp (ISO 8601 UTC).
   */
  createdAt: string;
  /**
   * Last update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
  /**
   * Logical-delete timestamp. **Only present when the request set `includeDeleted=true`** (§3.3) — the key is omitted entirely otherwise.
   */
  deletedAt?: string | null;
};

