export type CopyPlanDto = {
  /**
   * New plan name (required — copies must be distinguishable).
   */
  name: string;
  /**
   * Default true (v0.8, FR-M005) → the new row becomes a derivative of the source (parentPlanId = source). Send an explicit false for a simple copy that inherits the source parent.
   */
  asDerived?: boolean;
  /**
   * Subset of the create-body fields applied on top of the source snapshot — no immutables, and no `name` (it is the required top-level field; sending it here too → 400 E-VAL-001).
   */
  overrides?: UpdatePlanDto;
};

export type PlanChangeHistoryItemDto = {
  /**
   * History row ID.
   */
  id: string;
  /**
   * Plan the entry belongs to.
   */
  planId: string;
  /**
   * What happened to the plan. A §8 copy is recorded as `created` on the new plan.
   */
  eventType: 'created' | 'updated' | 'deleted' | 'restored';
  /**
   * Staff ID that made the change.
   */
  changedBy: string;
  /**
   * Staff display name (FR-S001 shows 変更者 by name). Null when the id resolves to no staff row.
   */
  changedByName: string | null;
  /**
   * v0.13 — The changer's CURRENT CRM role (staffs.position_id → positions.role, read at request time) — not the role held when the change was made. Null exactly when changedByName is null.
   */
  changedByRole: 'system' | 'headquarter' | 'manager' | 'staff' | 'trainer' | 'observer';
  /**
   * When the change was applied (ISO 8601 UTC).
   */
  changedAt: string;
  /**
   * Full plan snapshot at the time of the change: every `PlanDetailDto` field except the three derived counts, plus `usageHours`. Kept alongside `diff` so the UI can render point-in-time state without reconstruction.
   */
  snapshot: {
    [key: string]: unknown;
  };
  /**
   * Server-computed `{ field: { prev, next } }` against the immediately preceding history row — page boundaries do not matter, the server always sees the prior row. `prev` / `next` carry the raw field value, so their type varies by field. Null for the first `created` event.
   */
  diff: {
    [key: string]: {
      prev?: unknown;
      next?: unknown;
    };
  } | null;
  /**
   * Event context — `{ operationPath }`, plus `action` (image_add | image_update | image_delete) and `imageId` when the change came from an image EP. Null when the event carries none.
   */
  metadata: {
    [key: string]: unknown;
  } | null;
};

