export type CampaignDetailDto = {
  /**
   * Campaign ID.
   */
  campaignId: string;
  /**
   * Server-assigned display ID (§4.3, the キャンペーンID field). Format `CP-####`, unique, immutable — in a POST/PATCH/copy body → 400 E-VAL-001. Distinct from campaignCode.
   */
  campaignNumber: string;
  /**
   * Brand the campaign belongs to.
   */
  brandEnum: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
  /**
   * Human-readable operator identifier (`campaigns.campaign_code`, free-form, §4.3). Null when not set. Unique among non-deleted campaigns when present. Distinct from `promotion_codes.code` (G-06).
   */
  campaignCode: string | null;
  /**
   * Campaign name.
   */
  name: string;
  /**
   * Whether applications are currently being accepted.
   */
  isAccepting: boolean;
  /**
   * Acceptance status (§4.3 v0.4). `capacity_reached` = auto-stopped at `capacityLimit`; `stopped_manual` = stopped by an operator.
   */
  acceptingStatus: 'accepting' | 'stopped_manual' | 'capacity_reached';
  /**
   * First-come capacity limit. Null = uncapped.
   */
  capacityLimit: number | null;
  /**
   * Counted applications (§3.5): status IN (submitted, under_review, approved). Read from enrollment-svc; if it is unavailable the request fails (E-SYS-001) — never a silent 0.
   */
  appliedCount: number;
  /**
   * `max(capacityLimit − appliedCount, 0)`. Null when `capacityLimit` is null.
   */
  remainingCount: number | null;
  /**
   * Publish scope.
   */
  publishScope: 'all_stores' | 'specific_stores';
  /**
   * §4.3 v0.4 publication scope (`campaign_published_stores`), sorted by `storeCode`. **Empty when `publishScope = all_stores` — that means every store, not no store.** Replace it with PUT /campaigns/{id}/published-stores.
   */
  publishedStores: Array<CampaignPublishedStoreDto>;
  /**
   * §4.3 v0.4 base points per successful referral. **Null = not a referral campaign.**
   */
  referralBasePoints: number | null;
  /**
   * §4.3 v0.4 — the referral counter resets each 3/31 after the referrer reaches the top tier (APP-F-08 v1.1).
   */
  referralPointsAnnualReset: boolean;
  /**
   * §4.3 v0.4 step-up tiers, ascending by `minReferralCount`. Empty = flat `referralBasePoints`.
   */
  referralTiers: Array<CampaignReferralTierDto>;
  /**
   * §4.3 v0.4 — both axes for the caller's JWT `storeId`. **Null when the token has no store claim** (HQ; FC-company pattern B staff always).
   */
  myStoreUsage: CampaignMyStoreUsageDto | null;
  /**
   * Internal remarks. Null when unset.
   */
  remarks: string | null;
  /**
   * First day members may apply (YYYY-MM-DD).
   */
  recruitmentStart: string;
  /**
   * Last day members may apply (YYYY-MM-DD).
   */
  recruitmentEnd: string;
  /**
   * First day the discount is usable (YYYY-MM-DD). Null when unbounded.
   */
  usageStart: string | null;
  /**
   * Last day the discount is usable (YYYY-MM-DD). Null when unbounded.
   */
  usageEnd: string | null;
  /**
   * Which month the discount starts from. Null when unset.
   */
  applyStartMonth: 'first_month' | 'next_month' | 'specific_month';
  /**
   * The N in "start from month N". Non-null only when `applyStartMonth` is `specific_month`.
   */
  applyStartSpecificN: number | null;
  /**
   * How many months the discount runs for. Null when unset.
   */
  applyDurationMonths: number | null;
  /**
   * Plan the campaign discounts.
   */
  planId: string;
  /**
   * Plan name joined from the plan master. Empty string when the join misses.
   */
  planName: string;
  /**
   * Deprecated — stored as sent, ignored by pricing since the G-03 ruling of 2026-11-11 (the apply window decides the months).
   *
   * @deprecated
   */
  planDiscountMonth1: boolean;
  /**
   * Deprecated — stored as sent, ignored by pricing since the G-03 ruling of 2026-11-11 (the apply window decides the months).
   *
   * @deprecated
   */
  planDiscountMonth2: boolean;
  /**
   * How the plan discount is expressed. Null when no discount is set.
   */
  planDiscountType: 'fixed_amount' | 'percentage';
  /**
   * Plan discount amount — integer JPY for `fixed_amount`, percent (one decimal max) for `percentage`. Null when no discount is set.
   */
  planDiscountValue: number | null;
  /**
   * G-05 ADD-09 ① enrollment-fee discount type. Null when the campaign grants no enrollment-fee discount. Independent of the month flags — the enrollment fee is a one-time charge.
   */
  enrollmentFeeDiscountType: 'fixed_amount' | 'percentage';
  /**
   * Discount on `plans.enrollment_fee`. `percentage` 100 = full waiver (「キャンペーン免除」). Applied by API-098 §5.3 step 6b at application creation; existing applications keep their snapshot.
   */
  enrollmentFeeDiscountValue: number | null;
  /**
   * キャンペーン違約金 type (legacy `cancelFeeType`). Null = none.
   */
  cancellationFeeType: 'discount_amount' | 'cancellation_fee' | 'not_target';
  /**
   * Fixed 違約金, 税込 JPY, for `cancellation_fee`.
   */
  cancellationFeeAmount: number | null;
  /**
   * Tax rate included in `cancellationFeeAmount`.
   */
  cancellationFeeTaxRate: number | null;
  /**
   * 違約金 window in months from the 1st of the discount-start month (legacy `addMonthForFee`).
   */
  cancellationFeeMonths: number | null;
  /**
   * Per-option discounts. Empty when the campaign discounts only the plan.
   */
  campaignOptionDiscounts: Array<CampaignOptionDiscountDto>;
  /**
   * Options auto-attached on enrollment. Empty when none.
   */
  campaignAutoOptions: Array<CampaignAutoOptionDto>;
  /**
   * Active member contracts created under this campaign. Non-zero blocks edits / delete.
   */
  activeContractCount: number;
  /**
   * Enrollment applications still pending (status IN (submitted, under_review)), from enrollment-svc. Non-zero blocks edits / delete.
   */
  pendingApplicationCount: number;
  /**
   * Stores the campaign is linked to.
   */
  storeCount: number;
  /**
   * Promotion codes issued against this campaign.
   */
  promotionCodeCount: number;
  /**
   * Staff ID that created the campaign. Null for migrated rows.
   */
  createdBy: string | null;
  /**
   * Display name of the creating staff (§4.3). Null when createdBy is null or the name lookup misses.
   */
  createdByName: string | null;
  /**
   * Staff ID of the last update. Null when never updated.
   */
  updatedBy: string | null;
  /**
   * Display name of the last-updating staff (§4.3). Null when updatedBy is null or the lookup misses.
   */
  updatedByName: string | null;
  /**
   * Row creation timestamp (ISO 8601 UTC).
   */
  createdAt: string;
  /**
   * Last update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
  /**
   * Logical-delete timestamp. Always present on the detail projection (unlike the list one).
   */
  deletedAt: string | null;
};

export type CampaignOptionDiscountInputDto = {
  /**
   * Active option of the campaign brand (else 400 E-VAL-001).
   */
  optionId: string;
  /**
   * **Deprecated — ignored** (G-03 ruling 2026-11-11, App Bug-No45): the apply window (`applyStartMonth` / `applyStartSpecificN` / `applyDurationMonths`) alone decides which months are discounted. Still accepted and stored for older clients.
   *
   * @deprecated
   */
  discountMonth1?: boolean;
  /**
   * **Deprecated — ignored** (G-03 ruling 2026-11-11, App Bug-No45): the apply window (`applyStartMonth` / `applyStartSpecificN` / `applyDurationMonths`) alone decides which months are discounted. Still accepted and stored for older clients.
   *
   * @deprecated
   */
  discountMonth2?: boolean;
  /**
   * Set together with `discountValue`, or both null (E-CMP-005). The option is discounted in every month of the apply window from month 1 (the enrollment charge) on.
   */
  discountType?: 'fixed_amount' | 'percentage';
  /**
   * `>= 0`; `fixed_amount` = integer JPY, tax-included (API-088 v0.15); `percentage` = 0–100 with one decimal max. Out of range → 422 E-CMP-011.
   */
  discountValue?: number | null;
};

export type CampaignAutoOptionInputDto = {
  /**
   * Active option of the campaign brand (else 400 E-VAL-001).
   */
  optionId: string;
  /**
   * Unique values from the `members.gender` domain, or null = all members (the only way to say "everyone"). `["male","female"]` excludes `other` / `prefer_not_to_say`. Not an array / unknown value / duplicate → 422 E-CMP-012.
   */
  targetSexes?: Array<'male' | 'female' | 'other' | 'prefer_not_to_say'> | null;
};

export type CampaignReferralTierInputDto = {
  /**
   * `>= 1`, strictly ascending across the array, unique. `< 1` / duplicate / not ascending → 422 E-CMP-018.
   */
  minReferralCount: number;
  /**
   * Integer `>= 0` (else 400 E-VAL-001).
   */
  points: number;
};

export type CreateCampaignDto = {
  brandEnum: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
  campaignCode?: string | null;
  name: string;
  /**
   * false = created stopped (acceptance_stop_reason = manual).
   */
  isAccepting?: boolean;
  /**
   * First-come capacity cap (FR-002, §5.2 v0.4). Integer `>= 1`, or null = uncapped (`< 1` → 400 E-VAL-001).
   */
  capacityLimit?: number | null;
  remarks?: string | null;
  recruitmentStart: string;
  /**
   * `>= recruitmentStart` (else 400 E-VAL-001).
   */
  recruitmentEnd: string;
  usageStart?: string | null;
  /**
   * `>= usageStart` when both are set (else 400 E-VAL-001).
   */
  usageEnd?: string | null;
  applyStartMonth?: 'first_month' | 'next_month' | 'specific_month';
  applyStartSpecificN?: number | null;
  applyDurationMonths?: number | null;
  planId: string;
  /**
   * **Deprecated — ignored** (G-03 ruling 2026-11-11, App Bug-No45): the apply window (`applyStartMonth` / `applyStartSpecificN` / `applyDurationMonths`) alone decides which months are discounted. Still accepted and stored for older clients.
   *
   * @deprecated
   */
  planDiscountMonth1?: boolean;
  /**
   * **Deprecated — ignored** (G-03 ruling 2026-11-11, App Bug-No45): the apply window (`applyStartMonth` / `applyStartSpecificN` / `applyDurationMonths`) alone decides which months are discounted. Still accepted and stored for older clients.
   *
   * @deprecated
   */
  planDiscountMonth2?: boolean;
  /**
   * Set together with `planDiscountValue`, or both null (E-CMP-005). The plan is discounted in every month of the apply window.
   */
  planDiscountType?: 'fixed_amount' | 'percentage';
  /**
   * `>= 0`; `fixed_amount` = integer JPY, tax-included (API-088 v0.15); `percentage` = 0–100 with one decimal max. Out of range → 422 E-CMP-011.
   */
  planDiscountValue?: number | null;
  /**
   * G-05 ADD-09 ① enrollment-fee discount type. Must be sent together with `enrollmentFeeDiscountValue` (both null or both set) — exactly one → 422 E-CMP-005.
   */
  enrollmentFeeDiscountType?: 'fixed_amount' | 'percentage';
  /**
   * Discount on `plans.enrollment_fee`. JPY integer, tax-included, for `fixed_amount` (API-088 v0.8); 0–100 with one decimal max for `percentage`, where 100 = full waiver. Out of range → 422 E-CMP-011.
   */
  enrollmentFeeDiscountValue?: number | null;
  /**
   * キャンペーン違約金 — charged when the member withdraws within `cancellationFeeMonths` of the month the campaign discount starts (legacy `cancelFeeType`). `discount_amount` = the campaign discounts already billed are charged back; `cancellation_fee` = `cancellationFeeAmount`; `not_target` / null = none.
   */
  cancellationFeeType?: 'discount_amount' | 'cancellation_fee' | 'not_target';
  /**
   * Fixed 違約金, 税込 JPY (legacy `cancelFee`). Required when `cancellationFeeType` is `cancellation_fee` (E-VAL-001).
   */
  cancellationFeeAmount?: number | null;
  /**
   * Tax rate included in `cancellationFeeAmount` (legacy `taxRate`; 10 when null).
   */
  cancellationFeeTaxRate?: 0 | 8 | 10;
  /**
   * 違約金 window in months, counted from the 1st of the month the campaign discount starts; a withdrawal on or before that date is charged (legacy `addMonthForFee`). Null / 0 = no window.
   */
  cancellationFeeMonths?: number | null;
  /**
   * Unique optionId.
   */
  campaignOptionDiscounts?: Array<CampaignOptionDiscountInputDto>;
  /**
   * Unique optionId.
   */
  campaignAutoOptions?: Array<CampaignAutoOptionInputDto>;
  /**
   * Publication scope (FR-002 公開店舗設定, §5.2 v0.4).
   */
  publishScope: 'all_stores' | 'specific_stores';
  /**
   * Unique store ids (else 400 E-VAL-001). `specific_stores` → at least one; `all_stores` → omit or `[]` (else 422 E-CMP-017). Every store must exist and have `brandEnum` (else 422 E-CMP-010).
   */
  publishedStoreIds?: Array<string>;
  /**
   * Base referral points, integer `>= 1`, or null = not a referral campaign (`< 1` → 400 E-VAL-001).
   */
  referralBasePoints?: number | null;
  /**
   * Reset the referral counter each 3/31 after the top tier is reached (APP-F-08 v1.1). `true` needs `referralBasePoints` (else 422 E-CMP-018).
   */
  referralPointsAnnualReset?: boolean;
  /**
   * Step-up tiers (full replacement). Non-empty needs `referralBasePoints` (else 422 E-CMP-018).
   */
  referralTiers?: Array<CampaignReferralTierInputDto>;
};

