export type CampaignChangeHistoryItemDto = {
  /**
   * History row ID.
   */
  id: string;
  /**
   * Campaign the entry belongs to.
   */
  campaignId: string;
  /**
   * What happened to the campaign. A §15 copy is recorded as `created` on the NEW campaign. Capacity auto-stop / auto-resume and the §13 published-stores PUT write no row.
   */
  eventType: 'created' | 'updated' | 'deleted' | 'restored';
  /**
   * Staff ID that made the change.
   */
  changedBy: string;
  /**
   * Staff display name from the auth-svc staff directory. The spec (§14.3) marks it not-null; the server returns null when the directory has no name for `changedBy` (decision 2026-10-08, same as plan history) instead of inventing a placeholder.
   */
  changedByName: string | null;
  /**
   * v0.14 — The changer's CURRENT CRM role (staffs.position_id → positions.role, read at request time) — not the role held when the change was made. Null exactly when changedByName is null.
   */
  changedByRole: 'system' | 'headquarter' | 'manager' | 'staff' | 'trainer' | 'observer';
  /**
   * When the change was applied (ISO 8601 UTC).
   */
  changedAt: string;
  /**
   * Full campaign state after the change: every `campaigns` column (camelCase, `campaignId` = id) plus `campaignOptionDiscounts`, `campaignAutoOptions`, `publishedStores` and `referralTiers`.
   */
  snapshot: {
    [key: string]: unknown;
  };
  /**
   * Server-computed `{ field: { prev, next } }` against the row immediately before this one in the campaign's WHOLE history — the eventType / from / to filters are ignored for this, so a filtered view still shows the real change. Null for the first `created` event.
   */
  diff: {
    [key: string]: {
      prev?: unknown;
      next?: unknown;
    };
  } | null;
  /**
   * Event context — `{ operationPath }`. Null when the event carries none.
   */
  metadata: {
    [key: string]: unknown;
  } | null;
};

export type CampaignChangeHistoryListResponseDto = {
  /**
   * History entries, newest first (changed_at DESC, id DESC).
   */
  items: Array<CampaignChangeHistoryItemDto>;
  /**
   * page / limit paging. No `totalAllItems` — this EP has no includeTotalAll (§14.2).
   */
  pagination: PaginationDto;
};

