export type PromotionCodeUsageStatsDto = {
  /**
   * Issued count — always 1 (FR-016 reserved). **Detail only**; omitted from the list projection (§3.3/§4.3).
   */
  issuedCount?: number;
  /**
   * Redemptions so far.
   */
  usedCount: number;
  /**
   * Redemption cap. Null means unlimited.
   */
  maxUses: number | null;
  /**
   * Redemptions left (never negative). Null when `maxUses` is null.
   */
  remaining: number | null;
  /**
   * ROUND(usedCount * 100.0 / maxUses, 1) — one decimal place, half-up (3 / 2000 → 0.2). The same value as the CSV `usageRate`. Null when `maxUses` is null.
   */
  usageRate: number | null;
};

export type PromotionCodeListItemDto = {
  /**
   * Promotion code ID (§3.3 `id`).
   */
  id: string;
  /**
   * The code members type in.
   */
  code: string;
  /**
   * Campaign the code grants.
   */
  campaignId: string;
  /**
   * Internal distribution/purpose memo (§3.3 ★v0.4). ≤1000 chars, never shown to members. Null = unset.
   */
  description: string | null;
  /**
   * Joined from campaigns.name (§3.3).
   */
  campaignName: string;
  /**
   * Joined from campaigns.is_accepting (§3.3). Drives `campaign_unavailable`.
   */
  campaignIsAccepting: boolean;
  /**
   * Campaign `deleted_at` (§3.3). Non-null → the code is effectively unusable.
   */
  campaignDeletedAt: string | null;
  /**
   * Brand the code is valid for.
   */
  brandEnum: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
  /**
   * Where the code may be redeemed.
   */
  scopeType: 'brand_all' | 'issuer_store_only' | 'ogf_only' | 'member_referral' | 'family';
  /**
   * Issuing store. Null for brand-wide codes.
   */
  issuedStoreId: string | null;
  /**
   * Issuing store name. Null when there is no issuing store or the join misses.
   */
  issuedStoreName: string | null;
  /**
   * Whether the code string was generated or typed by staff (§3.3).
   */
  generationMethod: 'auto' | 'manual';
  /**
   * First day the code is valid (YYYY-MM-DD).
   */
  validFrom: string;
  /**
   * Last day the code is valid (YYYY-MM-DD). Past this, `effectiveStatus` becomes `expired`.
   */
  validTo: string;
  /**
   * Redemption cap. Null means unlimited.
   */
  maxUses: number | null;
  /**
   * Redemptions so far.
   */
  usedCount: number;
  /**
   * Derived redemption counters (§3.3 — list version omits issuedCount). Server-computed; do not recompute client-side.
   */
  usageStats: PromotionCodeUsageStatsDto;
  /**
   * The **persisted** status column.
   */
  status: 'active' | 'disabled' | 'expired' | 'exhausted';
  /**
   * §3.4: persisted `disabled` → `disabled`; else campaign deleted or not accepting → `campaign_unavailable`; else = `status`. `expired` / `exhausted` come from the persisted status (status batch / redemption), not from a read-time check.
   */
  effectiveStatus: 'active' | 'disabled' | 'expired' | 'exhausted' | 'campaign_unavailable';
  /**
   * Staff ID that issued the code (FR-001). Null for member_referral / family — issued by the member or the system, not by staff (v0.7).
   */
  createdBy: string | null;
  /**
   * Issuing staff name, `{last_name} {first_name}` of staffs (v0.7). Null when createdBy is null, or when the name lookup misses.
   */
  createdByName: string | null;
  /**
   * Row creation timestamp (§3.3).
   */
  createdAt: string;
  /**
   * Last update timestamp (§3.3).
   */
  updatedAt: string;
};

