export type TrainerHistoryEntryDto = {
  /**
   * History row ID.
   */
  id: string;
  /**
   * The trainer the event belongs to.
   */
  trainerId: string;
  /**
   * What happened. Both delete branches (deactivate-in-place and hard delete + redaction) record `deleted`; flipping `isActive` back to true records `restored`.
   */
  eventType: 'created' | 'updated' | 'deleted' | 'restored';
  /**
   * Whole-record snapshot at the time of the event: the trainer row plus all coach-type rows, minus read-time derived fields. A hard delete snapshots the row AFTER PII redaction. The FE reconstructs diffs by comparing adjacent snapshots.
   */
  snapshot: {
    [key: string]: unknown;
  };
  /**
   * Staff ID that made the change — a trainer-self edit resolves to the linked staff.
   */
  changedBy: string;
  /**
   * Display name of the staff. Empty string when the directory has no entry for them.
   */
  changedByName: string;
  /**
   * v0.9 — The changer's CURRENT CRM role (staffs.position_id → positions.role, read at request time) — not the role held when the change was made. Always set while the staff row resolves (null only on a staff-directory miss, where changedByName is '').
   */
  changedByRole: 'system' | 'headquarter' | 'manager' | 'staff' | 'trainer' | 'observer';
  /**
   * When the change was applied (ISO 8601 UTC).
   */
  changedAt: string;
};

