export type UpdateLessonScheduleTemplateRequestDto = {
  name?: string;
  /**
   * New lesson (v0.10). The resulting lesson + studio pair is re-checked (§6.9 #0).
   */
  lessonId?: string;
  /**
   * New studio (v0.10); null clears it. Re-checked against the lesson type (§6.9 #0).
   */
  studioId?: string | null;
  recurrenceType?: 'weekly' | 'biweekly' | 'monthly';
  /**
   * Days of week, 0 = Sunday … 6 = Saturday.
   */
  daysOfWeek?: Array<number>;
  startTime?: string;
  skipHolidays?: boolean;
  isActive?: boolean;
  /**
   * Optimistic lock (§7.6 — required on PATCH): the `updatedAt` you read. Missing = 400 E-VAL-001 (`required`); 409 E-LSC-014 when the row has changed since — the check is part of the UPDATE, so of two concurrent edits from the same read exactly one is written.
   */
  expectedUpdatedAt: string;
};

export type CreateLessonRecurrenceRequestDto = {
  /**
   * Source template (not deleted — else 422 E-LSC-019). Omit for the direct form.
   */
  templateId?: string;
  /**
   * Direct form: lesson master to repeat (required; existing and active). Template form: comes from the template (v0.10) — if sent it must equal the template lessonId.
   */
  lessonId?: string;
  /**
   * Direct form: owning store (required). Template form: comes from the template.
   */
  storeId?: string;
  /**
   * Direct form: studio of the store — required for a studio lesson, optional for body care, forbidden for personal training. Template form: comes from the template (v0.10) — if sent it must equal the template studioId; an explicit null is a value too (null against a template with a studio = 400 E-VAL-001, §6.5 #1a).
   */
  studioId?: string | null;
  /**
   * Assigned trainers, unique; index = display order; copied into every generated session. Needed (non-empty) on a published rule (E-LSC-006); unknown / duplicate = E-LSC-021. A trainer-role caller must include themselves — omitted on their unpublished draft, it defaults to them (§7.4).
   */
  trainerIds?: Array<string>;
  /**
   * First date of the run (YYYY-MM-DD) — today (JST) or later, else 400 E-VAL-001.
   */
  startDate: string;
  /**
   * Direct form: start time (HH:mm, store-local), the same for every session.
   */
  startTime?: string;
  /**
   * Direct form: cadence.
   */
  recurrenceType?: 'weekly' | 'biweekly' | 'monthly';
  /**
   * Direct form: days of week, 0 = Sunday … 6 = Saturday.
   */
  daysOfWeek?: Array<number>;
  /**
   * `until_date` (endDate) / `count` (maxOccurrences) are generated in full now; `unlimited` up to today + 3 calendar months, then topped up monthly.
   */
  endType: 'until_date' | 'count' | 'unlimited';
  /**
   * until_date: last date, on or after startDate. A rule that would generate more than 500 sessions is 400 E-VAL-001 (use unlimited). Not accepted with unlimited.
   */
  endDate?: string | null;
  /**
   * count: number of sessions (1–366). Not accepted with unlimited.
   */
  maxOccurrences?: number | null;
  /**
   * Direct form: skip the dates the §6.6.1 holiday chain matches — the store's temporary closures, holidays (`mst_holidays`) its holiday hours close, its regular closed day (a holiday with no holiday hours follows its weekday). False generates them and lists them in `holidayConflictDates`.
   */
  skipHolidays?: boolean;
  /**
   * Mode A (bookable in the app) / Mode B (CRM-only); copied to every session.
   */
  isPublished?: boolean;
  /**
   * Session capacity copied to every row. Null / omitted = the studio capacity (PT / body care: 1). Above the studio capacity within its buffer = W-LSC-011 in `warnings`; beyond = 422 E-LSC-004; not 1 on PT / body care = 422 E-LSC-005.
   */
  capacity?: number | null;
  /**
   * FR-016 trial seats for every session — studio lessons only (400 E-VAL-001 otherwise).
   */
  trialCapacityMode?: 'inclusive' | 'additive';
  /**
   * Trial seat limit — required with a mode; with `inclusive` it must be <= the session capacity.
   */
  trialCapacityLimit?: number | null;
};

