export type LessonScheduleListItemDto = {
  /**
   * Schedule ID.
   */
  id: string;
  /**
   * Lesson master being run.
   */
  lessonId: string;
  /**
   * Store the session runs at.
   */
  storeId: string;
  /**
   * Studio the session occupies. Null for sessions with no studio (e.g. personal training).
   */
  studioId: string | null;
  /**
   * The recurrence that generated this session. Null for one-off schedules.
   */
  recurrenceId: string | null;
  /**
   * Session date (YYYY-MM-DD).
   */
  scheduledDate: string;
  /**
   * Session start time (HH:mm).
   */
  startTime: string;
  /**
   * Session end time (HH:mm).
   */
  endTime: string;
  /**
   * Row-level capacity (v0.8): auto-set from the studio (PT/body_care = 1), operator-overridable within the studio band. Bookings enforce against this.
   */
  capacity: number;
  /**
   * Whether the session is visible to members.
   */
  isPublished: boolean;
  /**
   * Whether the session was cancelled. Cancellation is idempotent and keeps the row.
   */
  isCancelled: boolean;
  /**
   * Structured cancellation reason. Null unless `isCancelled`.
   */
  cancellationReasonCategory:
    | 'trainer_absence_sick'
    | 'trainer_absence_other'
    | 'facility_trouble'
    | 'weather_disaster'
    | 'insufficient_participants'
    | 'other';
  /**
   * Free-text cancellation note. Null unless `isCancelled`.
   */
  cancellationReason: string | null;
  /**
   * How trial-visit seats count against capacity — `inclusive` takes them from the lesson capacity, `additive` adds them on top. Null when trials are not configured.
   */
  trialCapacityMode: 'inclusive' | 'additive';
  /**
   * Trial-visit seat limit. Null when trials are not configured.
   */
  trialCapacityLimit: number | null;
  /**
   * Trainers assigned to the session.
   */
  trainerIds: Array<string>;
  /**
   * Staff ID that created the schedule. Null for generated rows with no actor.
   */
  createdBy: string | null;
  /**
   * Staff ID of the last update. Null when never updated.
   */
  updatedBy: string | null;
  /**
   * Row creation timestamp (ISO 8601 UTC).
   */
  createdAt: string;
  /**
   * Last update timestamp (ISO 8601 UTC).
   */
  updatedAt: string;
  /**
   * JOIN `lessons.name` ('' only if the lesson row is gone).
   */
  lessonName: string;
  /**
   * JOIN `lessons.lesson_type`. Null only if the lesson row is gone.
   */
  lessonType: 'studio' | 'personal_training' | 'body_care';
  /**
   * Additive (prototype timeline: the PT payment tag 月次プラン / 都度) — JOIN `lessons.fee_type`. Null only if the lesson row is gone.
   */
  feeType: 'free' | 'monthly_plan' | 'per_use';
  /**
   * Additive — JOIN `lessons.duration_minutes` (the session length; `endTime` also folds in the trainers' post-buffer). Null only if the lesson row is gone.
   */
  durationMinutes: number | null;
  /**
   * JOIN `studios.name`; null when `studioId` is null (PT).
   */
  studioName: string | null;
  /**
   * Prototype addition — the store badge on 自分のスケジュール rows (a trainer works at several stores). Resolved by the BFF from the store directory (contracts-svc); null when the directory does not know the store or is unreachable.
   */
  storeName: string | null;
  /**
   * Trainer display names (`last_name first_name`) in `trainerIds` order; '' for an id with no trainer row, so the two arrays stay aligned.
   */
  trainerNames: Array<string>;
  /**
   * Every live booking (reserved / pending / attended), trials included (§4.1). `trialBookingCount` is the trial part, so the normal bookings are `bookingCount − trialBookingCount`. Seats left: `capacity − bookingCount`, except on a `trialCapacityMode = additive` row, where trials sit on top: `capacity − (bookingCount − trialBookingCount)`.
   */
  bookingCount: number;
  /**
   * Live trial bookings — relevant when `trialCapacityMode` is set (inclusive: they also take seats from `capacity`).
   */
  trialBookingCount: number;
  /**
   * Prototype addition — on a one-to-one row (personal_training / body_care) the booking holding the slot; null on studio lessons and on an unbooked slot.
   */
  personalBooking: LessonSchedulePersonalBookingDto | null;
  /**
   * Prototype addition, `view=trainer-self` only (null in other views): up to three live bookers' names, oldest booking first — 「予約者: A、B、C 他N名」.
   */
  bookerNames: Array<string> | null;
  /**
   * Prototype addition, `view=trainer-self` only (null in other views): live bookers not named in `bookerNames` (the 他N名), trial ones included.
   */
  otherBookerCount: number | null;
};

