  /**
   * First date of the rule (YYYY-MM-DD).
   */
  startDate: string;
  /**
   * Start time of the rule (HH:mm). A session moved by PATCH keeps its own `startTime`.
   */
  startTime: string;
  /**
   * How the rule ends.
   */
