export type UpdateLessonScheduleRequestDto = {
  /**
   * Another lesson master. Flipping the lesson TYPE while live bookings exist = 409 E-LSC-015.
   */
  lessonId?: string;
  /**
   * Immutable: accepted only when equal to the current store (the edit form may resend it); a different store = 400 E-VAL-001 — re-create the schedule there.
   */
  storeId?: string;
  /**
   * Another studio of the same store; the kept capacity is re-validated against its band (E-LSC-004).
   */
  studioId?: string | null;
  /**
   * New run date (YYYY-MM-DD). A changed date must be a real one, today (JST) or later — the create rule (400 E-VAL-001); resending the current date is always accepted.
   */
  scheduledDate?: string;
  /**
   * New start time (HH:mm); a changed one re-derives endTime.
   */
  startTime?: string;
  /**
   * Full replacement of the trainer set (index = display order); endTime is re-derived. `[]` only on an unpublished schedule (E-LSC-006); unknown / deleted / duplicate ids = 422 E-LSC-021 with `details[]` per offending `trainerIds.<index>`. Omitted = the set is kept and not re-checked.
   */
  trainerIds?: Array<string>;
  /**
   * New capacity — 3-stage band check as on create; below the live non-trial bookings = 409 E-LSC-007.
   */
  capacity?: number;
  /**
   * Mode A / B publish flag.
   */
  isPublished?: boolean;
  /**
   * Trial mode (studio lessons only); null disables it — refused while live trial bookings exist (409 E-LSC-016).
   */
  trialCapacityMode?: 'inclusive' | 'additive';
  /**
   * Trial seat limit (send it with the mode).
   */
  trialCapacityLimit?: number | null;
  /**
   * Operator audit reason, stored on the `updated` history row. Missing / blank = 422 E-LSC-022.
   */
  changeReason: string;
  /**
   * Required optimistic lock (§7.2): the `updatedAt` you read. Missing = 400 E-VAL-001; stale = 409 E-LSC-014 — also when another edit commits between the read and the write (the UPDATE itself carries the check).
   */
  expectedUpdatedAt: string;
};

