export type MemberContractResponseDto = {
  /**
   * Contract ID.
   */
  id: string;
  /**
   * Contract state. Only `suspended` populates the two recess dates.
   */
  status: string;
  /**
   * Plan name, member-facing where one is set.
   */
  planName: string;
  /**
   * Plan type.
   */
  contractType: string;
  /**
   * Monthly fee **including tax** — the stored master as-is (API-151 v0.7).
   */
  monthlyFee: number;
  /**
   * The contract store.
   */
  store: MemberContractStoreDto;
  /**
   * When use began (date-only). Null when unset.
   */
  usageStartDate: string | null;
  /**
   * Contract start (date-only). Null when unset.
   */
  startDate: string | null;
  /**
   * Contract end (date-only). Null while open-ended.
   */
  endDate: string | null;
  /**
   * **Only populated while `status` is `suspended`** — an active contract reports null even if a resumed suspension left a value behind.
   */
  recessStartDate: string | null;
  /**
   * Suspension end. Same suspended-only rule as `recessStartDate`.
   */
  recessEndDate: string | null;
  /**
   * Display name — family + given, space-joined (the legacy header name), **not** the given name alone. From the member record, not the contract. Null when the member has neither part.
   */
  memberName: string | null;
  /**
   * Family name, under the legacy key `lastName`. Used as the greeting on the ~11 complete/checkout screens.
   */
  lastName: string | null;
  /**
   * Given name, from the member record rather than the contract. **Added 2026-09-07 beyond API-151 §3.2** for legacy parity (Phase 2 API List STT 80). Null when unset.
   */
  firstName: string | null;
  /**
   * Member number (reception number), shown on the complete/checkout screens.
   */
  memberCode: string | null;
  /**
   * Avatar image URL. Null when unset.
   */
  avatar: string | null;
  /**
   * Contract store name — the flat legacy spelling of `store.name`, which is still served. Both are the same value.
   */
  storeName: string | null;
  /**
   * Contract store id — the flat legacy spelling of `store.id`. UUID string (ADR-038 D8), where legacy sent an int.
   */
  storeId: string | null;
  /**
   * The **plan master** id (`contracts.plan_id`) — what the legacy field pointed at. **Not an alias of `id`/`memberContractId`**, which is the member's own contract row: the app tests this one for "has an active contract" and matches it against the plan list.
   */
  contractId: string | null;
  /**
   * Plan name — the legacy spelling of `planName`, same value (`plans.name_for_member` when set, else `plans.name`).
   */
  contractName: string | null;
  /**
   * The contract row id — the legacy spelling of `id`. Sent back as `primaryMemberContractId` on the withdrawal / suspension requests.
   */
  memberContractId: string | null;
  /**
   * Rented lockers (`contracts.locker_slot_id` → `locker_slots`). `[]` when the contract holds no slot, and **at most one entry**: v2 links a single slot per contract row, where legacy could list several. **Added 2026-09-07 beyond API-151 §3.2** for legacy parity (STT 80). The key is `lockers` because that is what legacy actually returned — its Swagger says `locker` only because the DTO carried `@ApiProperty({ name: 'locker' })` over a property named `lockers`, and the shipped app parses `lockers`.
   */
  lockers: Array<MemberContractLockerDto>;
};

