export type LegacyWithdrawalStatusDto = {
  /**
   * Application **UUID** (legacy 休会退会ID was an int).
   */
  id: string;
  /**
   * Legacy `WithdrawalTypeEnum`, derived from which table the row is in plus its `reason_code`: `temporary_recess` → `temporaryRecess` (HQ-only 臨時休会), `forced` → `systemWithdrawal` (強制退会).
   */
  type: 'recess' | 'withdrawal' | 'systemWithdrawal' | 'temporaryRecess';
  /**
   * Legacy `StatusWithdrawalEnum`. **Derived, not stored**: an `active` 休会 reads `recessing` once its `startDate` has arrived and `processWaiting` before that — the application row never moves to a separate state for it. `completed` → `processed`.
   */
  status: 'processWaiting' | 'processed' | 'cancelled' | 'recessing';
  /**
   * 適用開始日 — recess start for a 休会; the scheduled withdrawal date for a 退会 (legacy used the same column).
   */
  startDate: string | null;
  /**
   * 適用終了日. **Always null on a 退会** — a withdrawal has no window, as in legacy.
   */
  endDate: string | null;
  /**
   * 主契約ID — the contract **UUID**, where legacy held a `member_contracts` int.
   */
  primaryMemberContractId: string | null;
  /**
   * 規約ID. **Always null** — legacy pinned the agreed terms revision onto the application row; API-076 records consent in its own table, so the id is not reachable from here.
   */
  termId: number | null;
  /**
   * 規約既読日時. **Always null**, for the same reason as `termId`.
   */
  termReadAt: string | null;
  /**
   * 実際適用日. **Always null** — legacy stamped it when its batch applied the row; no column records it here.
   */
  applicableDate: string | null;
  /**
   * 休会実際終了日. **Always null** — it was stamped when a recess was ended early, and the 早期復帰 flow (`PUT /withdrawal-recess/recess/restore`) has no counterpart in the new design.
   */
  recessingEndDate: string | null;
  /**
   * 代理申請者ID — the staff **UUID** who filed it for the member. Null on a self-service application, which is every row an app caller can reach.
   */
  adminId: string | null;
  /**
   * 取消不可フラグ. **Always `true`**, the legacy column default. Legacy read it on no member path and real cancellability is derived from status + dates, so it is echoed rather than inverted into a guess about a flag whose name and default disagree.
   */
  cancelFlag: boolean;
  /**
   * 備考 — the member's own free-text reason.
   */
  description: string | null;
  /**
   * 作成日時.
   */
  createdAt: string;
  /**
   * 更新日時. Falls back to `createdAt` when the row has never been updated.
   */
  updatedAt: string;
};

