export type LegacyLockerSlotDto = {
  /**
   * Slot **UUID** (legacy int).
   */
  id: string;
  /**
   * Legacy numeric `code` — `Number(slotCode)` (API-136 §11.2), so the canonical `"012"` is `12`. **Null** when the slot code is not all digits.
   */
  code: number | null;
  /**
   * Legacy `LockerStatusEnum` (API-136 §11.3): `1` in use, `2` available, `3` cleaning (released but not yet cleaned — derived). `2` only for a slot that also has a fee option, as in legacy (`isAvailable && optionId`): an unpriced slot cannot be contracted.
   */
  status: 1 | 2 | 3;
  /**
   * Slot size in **cm**, as an object — the app decodes `{ widthCm, heightCm, depthCm }` (fixed 2026-10-12; this used to be the opaque string `"w30xh40xd45"` of API-136 §11.4, which the app cannot read). Null when the slot has no complete size.
   */
  lockerSlotSize: LegacyLockerSlotSizeDto | null;
  /**
   * Monthly fee, **tax-inclusive** — legacy `options.fee` was 「料金(税込)」 and the app reads this as `priceAfterTax`. The v2 master is 税込 too (API-085 v0.12), passed through. `0` for a slot with no fee option, as in legacy (`option?.fee ?? 0`).
   */
  fee: number;
  /**
   * Percent. `0` for a slot with no fee option, as in legacy.
   */
  taxRate: number;
  optionId: string | null;
  /**
   * **Always null** — the canonical member read exposes no PIN. Legacy did on `LockerSlotDto`; the PIN reaches the member through the contract endpoints instead.
   */
  pinCode: string | null;
};

