export type LegacyAppTrainingSettingsDto = {
  /**
   * 重量単位.
   */
  weightUnit: 'kg' | 'lbs';
  /**
   * 距離単位.
   */
  distanceUnit: 'km' | 'mile';
  /**
   * 測定単位.
   */
  measurementUnit: 'cm' | 'in';
  /**
   * タイマー音 — from the API-019 timer settings. Same three values as legacy.
   */
  alarmSound: 'default' | 'futuristic' | 'whistle';
  /**
   * 音量 — v2 `volumePercent`. Untouched settings read 80 (API-019 initial) where legacy read 50.
   */
  volume: number;
  /**
   * 休憩時間の初期値, in **seconds** — v2 stores `restTimerMinutes`/`restTimerSeconds` and this multiplies them out. The v2 default (1m30s) is legacy's default (90s).
   */
  breakTimeDefault: number;
  /**
   * タイマーの表示方法 — v2 `displayMode`: `always`=`modal` (bottom-sheet countdown), `only`=`footer`.
   */
  displayTimer: 'always' | 'only';
  /**
   * 振動 — v2 `isVibrationEnabled` (API-019).
   */
  vibration: boolean;
  /**
   * 通知の更新.
   */
  notificationUpdate: boolean;
  /**
   * 前回のトレーニング値.
   */
  lastTrainingValue: 'takeover' | 'initial';
  /**
   * 個別休憩タイマー表示.
   */
  isBreakTimeDisplay: boolean;
  /**
   * トレーニング種目別メモ.
   */
  isExerciseNoteDisplay: boolean;
  /**
   * セット毎の履歴表示.
   */
  isSetHistoryDisplay: boolean;
  /**
   * セット毎のRPE表示.
   */
  isRpeDisplay: boolean;
  /**
   * 週間目標の繰り返し.
   */
  isWeeklyRepeatGoal: boolean;
};

export type LegacyAppTrainingSettingsPatchDto = {
  weightUnit?: 'kg' | 'lbs';
  distanceUnit?: 'km' | 'mile';
  measurementUnit?: 'cm' | 'in';
  /**
   * Routed to the API-019 timer settings.
   */
  alarmSound?: 'default' | 'futuristic' | 'whistle';
  /**
   * Routed to the API-019 timer settings as `volumePercent`.
   */
  volume?: number;
  /**
   * Seconds; split into the v2 minutes/seconds pair. Legacy accepted any number, so a value over 59m59s is a 400 here.
   */
  breakTimeDefault?: number;
  /**
   * Routed to the API-019 timer settings as `displayMode`.
   */
  displayTimer?: 'always' | 'only';
  /**
   * Routed to the API-019 timer settings as `isVibrationEnabled`.
   */
  vibration?: boolean;
  notificationUpdate?: boolean;
  lastTrainingValue?: 'takeover' | 'initial';
  isBreakTimeDisplay?: boolean;
  isExerciseNoteDisplay?: boolean;
  isSetHistoryDisplay?: boolean;
  isRpeDisplay?: boolean;
  isWeeklyRepeatGoal?: boolean;
};

