export type LegacyExerciseDetailDto = {
  id: string;
  name: string;
  /**
   * `exercises.category`, unmapped — the v2 category axis, not legacy`s `ExerciseCategoryEnum`.
   */
  mainCategory: string;
  /**
   * See `coreMuscle` on the list item.
   */
  coreMuscle: string;
  /**
   * See `secondaryMuscle` on the list item.
   */
  secondaryMuscle: Array<string | null> | null;
  /**
   * Legacy `UnitTypeEnum`; see the list item.
   */
  unitType: string;
  /**
   * See `image` on the list item.
   */
  image: {
    [key: string]: unknown;
  } | null;
  /**
   * Same URL as `image`: v2 keeps one picture per movement, where legacy stored two renditions of it.
   */
  thumbnail: {
    [key: string]: unknown;
  } | null;
  description: {
    [key: string]: unknown;
  } | null;
  /**
   * Legacy `LevelEnum`, mapped from `exercises.level` (easy/moderate/hard).
   */
  level: 'beginner' | 'intermediate' | 'advanced';
  /**
   * `exercises.equipment`, unmapped — v2 has 10 codes against legacy`s tool list (board STT 12).
   */
  equipment: string;
  breakTime: number;
  videoUrl: {
    [key: string]: unknown;
  } | null;
  /**
   * Legacy `HandUsageTypeEnum`, from `exercises.limb_usage`.
   */
  handUsageType: 'both' | 'single';
  relatedExercises: Array<LegacyRelatedExerciseDto>;
  /**
   * The movement steps. Synthesised from `exercise_descriptions` — legacy stored one row per step with a `position`, v2 one row per language with a named column per step, so start/movement/final/return become positions 1–4.
   */
  trainingMethods: Array<LegacyTrainingMethodDto>;
  /**
   * Legacy`s position-0 detail row — `exercise_descriptions.training_point` here.
   */
  tip: LegacyTrainingMethodDto | null;
  isRecordGrip: boolean;
  isRecordGripOrientation: boolean;
  isRecordHandOrFootWidth: boolean;
  isRecordCenterOfGravity: boolean;
  isRecordBenchPress: boolean;
  isRecordSquat: boolean;
  isRecordDeadlift: boolean;
  /**
   * **Always null.** Legacy took the member`s note from their most recent routine entry for this movement; v2`s `routine_exercises` has no note column (only `hq_comment`, which is HQ copy on official routines).
   */
  note: {
    [key: string]: unknown;
  } | null;
};

export type LegacyCreateExerciseBodyDto = {
  name: string;
  /**
   * Legacy `ExerciseCategoryEnum` code; mapped onto the v2 category axis.
   */
  mainCategory: string;
  /**
   * Legacy muscle code, stored verbatim — the coarse v2 axis would lose what the member picked.
   */
  coreMuscle: string;
  /**
   * Part name is `secondaryMuscle[]`. v2 keeps ONE secondary muscle, so the first value is stored and the rest dropped.
   */
  'secondaryMuscle[]'?: Array<string>;
  /**
   * Legacy `EquipmentEnum` code.
   */
  equipment: string;
  /**
   * Legacy `UnitTypeEnum`. `distanceDuration` and `weightDistance` are **rejected**: v2 has no equivalent exercise type, and filing one as something else would misread every set recorded against it.
   */
  unitType:
    | 'weightReps'
    | 'bodyweightReps'
    | 'weightedBodyweight'
    | 'assistedBodyweight'
    | 'duration'
    | 'durationWeight';
  /**
   * Rest-timer default, seconds.
   */
  breakTime: number;
  handUsageType: 'both' | 'single';
  /**
   * One image. Uploaded to the media store server-side; the key is stored on the movement.
   */
  image?: Blob | File;
  isRecordGrip?: boolean;
  isRecordGripOrientation?: boolean;
  isRecordHandOrFootWidth?: boolean;
  isRecordCenterOfGravity?: boolean;
  isRecordBenchPress?: boolean;
  isRecordSquat?: boolean;
  isRecordDeadlift?: boolean;
};

