export type LegacyUncollectedAmountDto = {
  /**
   * Legacy `uncollectedAmount` — the canonical `amount`, renamed. The sum of the **outstanding remainder** across bills (total minus already collected), not their face values. `0` when nothing is owed.
   */
  uncollectedAmount: number | null;
  /**
   * Legacy `saleIds` — the canonical `billingIds`, renamed and **passed through as UUID strings** (ADR-038 D8; the app moves this field and `financialInfoId` from `int` to `String`). These are what `POST /sbps-link/request` must send back to select which bills to pay, so they are forwarded verbatim rather than dropped. `[]` when nothing is owed.
   */
  saleIds: Array<string>;
  /**
   * Not a legacy field (additive). `true` while the member, or anyone in the member's family, has an unpaid bill. A family member (child) always gets `uncollectedAmount: 0` and `saleIds: []`; show the 「主会員のお支払いが確認できていないため…」 message when this is `true` (APP-F-03 FR-S006).
   */
  familyUnpaid?: boolean;
};

export type LegacyStreakEntryDto = {
  /**
   * The open card's visit days — distinct JST dates (`YYYY-MM-DD`), **newest first**, at most 10. On the day a card closes it is that card's ten days instead (the app recognises “10 days, newest is today” as the completion). `[]` right after a card has closed.
   */
  streakLog: Array<string>;
  /**
   * How many cards have **closed** (every ten distinct visit days close one) — legacy’s count of 「スタンプ」 points. Not the stamps on the open card; the app shows `total × 10 + streakLog.length`.
   */
  total: number;
  /**
   * When the newest card closed — the first gate entry of its tenth visit day. `null` until a card has closed (or if that day cannot be read).
   */
  completedAt: string | null;
};

export type LegacyMemberQrCodeDto = {
  /**
   * Legacy `qrCode` — the canonical `qrPayload`, renamed. Opaque: render it, do not parse it. **Short-lived and single-use**: each call invalidates the previously issued token, so re-request it rather than caching. The canonical response also carries `expiresAt`/`ttlSeconds`; legacy had neither and the app reads neither, so they are dropped here.
   */
  qrCode: string | null;
};

export type LegacyLockerUnitDto = {
  /**
   * Cabinet id — pass it to `lockers/lockers-slot?lockerId=` to list its slots.
   */
  id: string;
  /**
   * Area letter A–Z, from the location master. Legacy held the same letter in a `lockerArea` enum column.
   */
  lockerArea: string | null;
  /**
   * First cabinet photo, as a delivery URL. Null when the cabinet has none.
   */
  lockerImage: string | null;
  /**
   * Floor-map X placement. **Not geographic and not pixels** — API-100 §6.3 stores a fraction `0.0–1.0` of the floor-plan image measured from its top-left, so that re-uploading the plan or rendering it at another zoom keeps placements valid. Sent as a string because legacy typed this column `varchar`. Multiply by the rendered plan width; treating it as a pixel offset puts every cabinet in the top-left corner.
   */
  longitude: string | null;
  /**
   * Floor-map Y placement — same `0.0–1.0` fraction rule as `longitude`, measured downward from the top edge.
   */
  latitude: string | null;
  /**
   * **Always null** — v2 has no direction column on a cabinet; legacy defaulted it to `left`. Null rather than a guessed `left`, because the app renders the opening side from it and a wrong side is worse than none. Constrained to legacy's four values if it is ever populated: the app's `LockerDirection` has no unknown member, so any other string is a decode error.
   */
  direction: 'left' | 'right' | 'top' | 'bottom';
};

export type LegacyLockersUnitResponseDto = {
  /**
   * The store's floor-plan image, as a delivery URL. Null when the store has not uploaded one.
   */
  gymMapImage: string | null;
  /**
   * The store's active cabinets, filtered to `optionId` when that query param is given. `[]` is a valid answer.
   */
  lockers: Array<LegacyLockerUnitDto>;
};

