export type LegacyTransferStoreDto = {
  /**
   * Transfer application id.
   */
  id: string | null;
  /**
   * **Always null** — legacy keyed the transfer to a member-contract row; v2's application records the stores and the member, not a contract id.
   */
  sourceContractId: string | null;
  /**
   * The store being left (canonical `fromStoreId`).
   */
  sourceStoreId: string | null;
  /**
   * The store being moved to (canonical `toStoreId`). The app fetches this store to name it on screen.
   */
  destinationStoreId: string | null;
  /**
   * Effective date, date-only. Null until scheduled.
   */
  scheduledTransferDate: string | null;
  /**
   * **Always `transferProcessing`** when a row is returned. The canonical status vocabulary (`pending`/`active`/…) is mapped down to legacy's single in-flight value on purpose: the app's `TransferStoreStatus` knows only this one and falls back to `unknown`, and its screen renders the pending-transfer block **only** on an exact match — so passing the v2 string through would silently blank the block.
   */
  transferStatus: 'transferProcessing';
  /**
   * Reason text. Null when unset — the canonical route allows a transfer with no reason.
   */
  transferReason: string | null;
};

export type LegacyTransferStoreRequestDto = {
  /**
   * Accepted and **ignored**: 移籍元 is the caller's main contract (API-142 §3.2), not a client-sent id.
   */
  sourceContractId?: string | null;
  /**
   * Accepted and ignored — a transfer keeps the plan; plan changes are a separate flow.
   */
  destinationContractId?: string | null;
  /**
   * Accepted and **ignored**, for the same reason as `sourceContractId`.
   */
  sourceStoreId?: string | null;
  /**
   * Destination store **UUID** → canonical `toStoreId`.
   */
  destinationStoreId: string;
  /**
   * The date the member picked. A bare date or a local timestamp is taken as that calendar day; a timestamp carrying `Z` / an offset is converted to the JST day.
   */
  scheduledTransferDate: string;
  /**
   * Free text (the app joins its checkbox labels and note with newlines). Sent as `reasonCode: "other"` + `reasonDetail` (API-142 §11.4), first 500 characters.
   */
  transferReason?: string | null;
};

