export type LegacyPointBalanceEntryDto = {
  /**
   * Yamauchi payment type. **Always `point`** here: the shipped app reads only this entry (`GetExternalPointResult.pointBalance`) and v2's ledger has no payment-type axis.
   */
  ptype: string;
  /**
   * Spendable balance — the latest ledger row's running total, the same derivation as the canonical `GET /api/v1/points/balance`.
   */
  available: number;
};

export type LegacyPointCumulusEntryDto = {
  /**
   * Yamauchi payment type. Always `point` — see `LegacyPointBalanceEntryDto.ptype`.
   */
  ptype: string;
  /**
   * Lifetime **earned** points, i.e. positive movements only. Spends and expiries do not reduce it: the app derives the member rank (総累計ポイント) from this number, and a rank that dropped when you spent points would be wrong.
   */
  total: number;
};

export type LegacyPointResultDto = {
  /**
   * Spendable balances. **Always exactly one entry** (`ptype: point`), `available: 0` when the ledger is empty. Not brand-gated: ENJOY (JOYFIT) points are in launch scope since TBD-007 closed 2026-08-06.
   */
  balance: Array<LegacyPointBalanceEntryDto>;
  /**
   * Lifetime totals. **Always exactly one entry** (`ptype: point`), `total: 0` when the ledger is empty.
   */
  cumuluses: Array<LegacyPointCumulusEntryDto>;
};

export type LegacyGetPointResponseDto = {
  /**
   * The payload, wrapped exactly as the external API wrapped it — the app reads `result`, not the root.
   */
  result: LegacyPointResultDto;
};

export type LegacyExternalAddMemberRequestDto = {
  /**
   * Legacy brand selector for the external point server. **Ignored** — the brand is the member's own.
   */
  brand?: string;
  /**
   * Legacy int member id. **Ignored** — the member is the JWT subject.
   */
  memberId?: string;
  /**
   * Legacy account status sent to the external server. **Ignored**.
   */
  sts?: string;
  /**
   * Legacy "talk to the old point server" switch. **Ignored**.
   */
  isOld?: boolean;
};

export type LegacyExternalAddMemberResponseDto = {
  /**
   * Always `ok`: the v2 point ledger needs no member registration, so there is nothing that can fail.
   */
  status: 'ok';
};

export type LegacyMonthlyPointDto = {
  /**
   * **Two-digit year** `YY-MM`, as fitness-api sent it. Not a typo and not safe to "fix": the app parses this as `DateTime(2000 + YY, MM)` and re-formats it as `yyyy-MM` for `detail-monthlies`, so a four-digit year here becomes the year 4026 there and the detail list comes back empty. Buckets are cut in **JST**.
   */
  month: string;
  /**
   * Points **earned** in the month — positive movements only, matching legacy's `SUM(CASE WHEN endpoint = 'give_point' …)`. A month with more spending than earning still reports what was earned.
   */
  totalPoints: number;
  /**
   * Derived, never stored: the current JST month is still accruing → `PENDING`; every earlier month → `CONFIRMED`. Legacy never emitted `CANCELED` here either.
   */
  status: 'PENDING' | 'CONFIRMED';
};

export type LegacyPointHistoryDto = {
  /**
   * **Always null.** The ledger id is a UUID and the app declares `int?`, so sending it would be a Dart `TypeError`; the app's mapper drops the field, so null costs nothing.
   */
  id: number | null;
  /**
   * Point **magnitude** (never negative). Direction lives in `type` — v2 stores one signed number, legacy stored an amount plus a direction.
   */
  point: number;
  /**
   * Derived from the sign of the ledger movement: negative → `use_point`, otherwise `give_point`.
   */
  type: 'give_point' | 'use_point';
  /**
   * Row label, standing in for legacy's partner-supplied `svalue`: the movement's own description when it has one, else the JP name of its event type (an unknown event type echoes its code rather than blanking the row). Activity awards store legacy's own `svalue` as their description — `来館` / `トレーニング記録` / `体重体脂肪記録` / `レッスン参加` — so the row reads exactly as it did in legacy.
   */
  name: string | null;
  /**
   * **`YYYY-MM-DD HH:mm` in JST, not ISO-8601** — legacy's format, which the app parses as a naive local `DateTime`. It is the ledger timestamp: v2 has no external sync step, so there is no separate synced-at time.
   */
  syncedAt: string | null;
};

export type LegacyLatestRewardDto = {
  /**
   * Ledger row id (UUID — ADR-038 D8).
   */
  id: string | null;
  /**
   * Legacy `svalue` — the row's description, or the JP label for its event type when it has none.
   */
  svalue: string | null;
  /**
   * The source row the points came from (training session, referral, …), or null when the award has no source. **Must round-trip**: the training-result screen shows the popup only when this equals the session it just finished.
   */
  scopeId: string | null;
  /**
   * Legacy's name for what the points were for, mapped from the v2 `eventType`. Constrained to values the app's `PointScopeType` knows: that enum decodes **without** an `unknownEnumValue`, so an unrecognised string is an `ArgumentError`, not a null. `stamp` never appears — stamps are not ledger rows.
   */
  scopeType: 'entry' | 'training' | 'invitation' | 'purchase' | 'reserve' | 'step' | 'manual';
  /**
   * Point **magnitude** (never negative); direction is in `endpoint`.
   */
  point: number | null;
  /**
   * Derived from the sign of the ledger movement.
   */
  endpoint: 'give_point' | 'use_point';
};

export type LegacyPointUseRequestDto = {
  /**
   * Sent by the shipped app; **ignored** (the member is the JWT subject).
   */
  memberId?: string;
  /**
   * Points to spend. At most the balance (E-RWD-003) and at most the chosen line's `fee` from `GET plan-options/me` (E-RWD-002) — the same two caps the app applies.
   */
  usePoint: number;
  /**
   * `memberContractId` of one entry of `GET /api/v1/fitness-member/plan-options/me` — the plan line or one monthly option line of the caller's current contract. Any other id is 404 E-OPT-004.
   */
  scopeId: string;
};

export type LegacyPointUseResponseDto = {
  /**
   * Ledger row id of the spend.
   */
  id: string;
  memberId: string;
  /**
   * Signed, as legacy stored it: a use is negative.
   */
  point: number;
  endpoint: 'use_point';
  /**
   * The contract line the points will be deducted from (the request `scopeId`).
   */
  scopeId: string;
  /**
   * Balance after the use.
   */
  pointBalance: number;
  createdAt: string;
};

export type LegacyPostalAddressDto = {
  /**
   * 郵便番号 — 7 digits, no hyphen.
   */
  postalCode: string;
  /**
   * 都道府県コード — JIS X 0401, 2 digits. The app maps it with `int.tryParse` to its prefecture picker.
   */
  prefectureCode: string;
  /**
   * 市区町村コード — the last 3 digits of the JIS X 0402 municipality code (legacy split the 5-digit code 2 + 3).
   */
  cityCode: string;
  /**
   * 都道府県カナ — half-width katakana, as published by Japan Post.
   */
  prefectureKana: string;
  /**
   * 市区町村カナ — half-width katakana.
   */
  cityKana: string;
  /**
   * 町域カナ — half-width katakana; empty when `suburb` is empty.
   */
  suburbKana: string;
  /**
   * 都道府県
   */
  prefecture: string;
  /**
   * 市区町村
   */
  city: string;
  /**
   * 町域. **Empty string, never null**, for a code that covers the rest of a city (KEN_ALL's 「以下に掲載がない場合」, which legacy passed through and the app then wrote into 住所1). A long 町域 that KEN_ALL splits over several lines is returned joined into one row.
   */
  suburb: string;
};

