export type AdminStaffPermissionControllerListStaffData = {
  body?: never;
  path?: never;
  query?: {
    page?: number;
    limit?: number;
    /**
     * Partial match on last/first name, their kana, and the login email (API-082 §5.2 ★v0.9 — the parameter is `keyword`). Case-insensitive substring on all five; `%` and `_` are matched literally, not as wildcards. `emailDomain` is the separate EXACT match on the domain part; it does not answer a pasted address or a local-part fragment.
     */
    keyword?: string;
    /**
     * Exact match on the email domain part (Y-14 domain detail screen).
     */
    emailDomain?: string;
    role?: 'system' | 'headquarter' | 'manager' | 'staff' | 'trainer' | 'observer';
    positionId?: string;
    storeId?: string;
    /**
     * The CRM ステータス dropdown (有効 / 無効 / 招待中) maps to this 1:1. Derived server-side and also returned on every row.
     */
    status?: 'active' | 'inactive' | 'invited';
    /**
     * Raw `staffs.is_active` — a different question from `status`, which also accounts for whether onboarding completed. Both may be sent.
     */
    isActive?: boolean;
    /**
     * `invited` = the newest invite token is still outstanding. Derived from `auth_tokens`, not a column.
     */
    inviteStatus?: 'invited' | 'accepted';
    /**
     * Store area (free text on `stores.area`, matched exactly). Resolved to store ids on contracts-svc; an area matching no store returns an empty page.
     */
    area?: string;
    /**
     * Unknown keys fall back to `createdAt`. `lastLogin` puts never-logged-in rows last in BOTH directions.
     */
    sort?: 'id' | 'name' | 'position' | 'status' | 'lastLogin' | 'createdAt';
    order?: 'asc' | 'desc';
  };
  url: '/api/v1/admin/staff';
};

