export type AdminTransferControllerListData = {
  body?: never;
  path?: never;
  query?: {
    /**
     * CONV-001 §3.4.1 — when true, `pagination.totalAllItems` carries the baseline count (optional filters reset, role scope kept).
     */
    includeTotalAll?: boolean;
    /**
     * Filter by the transfer brand (source store’s brand; transfers are intra-brand).
     */
    brandEnum?: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
    /**
     * API-091 v0.5 §3.2 — filter by the transfer brand group (source store’s group). Combines with `brandEnum` / `fromStoreId` by intersection (AND); a contradictory pair such as `brandGroup=FIT365&brandEnum=Joyfit24` yields an empty page, not a 400.
     */
    brandGroup?: 'JOYFIT' | 'FIT365';
    /**
     * Source store filter.
     */
    fromStoreId?: string;
    /**
     * Destination store filter.
     */
    toStoreId?: string;
    /**
     * API-091 v0.9 §3.2 — the store picked in the CRM header: matches an application whose source OR destination store is this store. ANDed with every other filter and with the caller's role scope (a store outside the scope gives an empty page, not an error). Omit it when the header shows all stores.
     */
    storeId?: string;
    /**
     * Current status filter (DB value).
     */
    status?:
      | 'submitted'
      | 'pending_source_approval'
      | 'pending_destination_approval'
      | 'completed'
      | 'rejected';
    /**
     * Applied-date (created_at, JST) inclusive lower bound.
     */
    appliedFrom?: string;
    /**
     * Applied-date inclusive upper bound (≥ appliedFrom).
     */
    appliedTo?: string;
    /**
     * v0.3 — read-time auto-transfer eligibility. Implicitly scopes to JOYFIT × pending_source_approval.
     */
    autoTransferEligibility?: 'eligible' | 'excluded';
    page?: number;
    limit?: number;
    /**
     * `status` sorts by PostgreSQL enum definition order.
     */
    sort?: 'createdAt' | 'scheduledTransferDate' | 'status';
    order?: 'asc' | 'desc';
  };
  url: '/api/v1/admin/transfer-applications';
};

