export type GateDeviceControllerAuthenticateData = {
  body: {
    credentialType: 'qr' | 'nfc';
    qrPayload?: string | null;
    /**
     * 16 uppercase hex (I-CODE SLIX2)
     */
    nfcUid?: string | null;
    /**
     * Debug-only; never trusted.
     */
    hintEventType?: 'entry' | 'exit' | 'companion_entry';
    scannedAt?: string | null;
  };
  headers: {
    /**
     * Set by the load balancer, never by a client: the URL-encoded PEM of the client certificate it verified over mTLS (GATE-01 gate tablet, AWS IoT certificate). Read only when GATE_TABLET_MTLS_ENABLED=true; the tablet is then identified by the certificate id and the three device headers are not needed.
     */
    'x-amzn-mtls-clientcert-leaf'?: string;
    /**
     * Must be absent — a Bearer token on the device channel is rejected (E-AUTH-090).
     */
    authorization?: string;
    /**
     * Client UUIDv4, one per scan; the same key within 60 s replays the first response.
     */
    'x-idempotency-key': string;
    /**
     * Required unless the caller is a gate tablet over mTLS.
     */
    'x-device-secret'?: string;
    /**
     * Required unless the caller is a gate tablet over mTLS.
     */
    'x-relay-controller-id'?: string;
    /**
     * connected_devices.id (entry_gate | exit_gate). Required unless the caller is a gate tablet over mTLS.
     */
    'x-device-id'?: string;
  };
  path?: never;
  query?: never;
  url: '/api/v1/gate/authenticate';
};

export type GateDeviceControllerAuthenticateErrors = {
  /**
   * JWT on device channel (E-AUTH-090), bad secret (E-AUTH-091), or bad idempotency key (E-AUTH-093).
   */
  401: unknown;
  /**
   * Unknown device or controller, a device/controller pairing mismatch, or an unlinked tablet (E-VIS-007); credential resolves to no member (E-VIS-203). A gate or controller that is out of service, or a gate before its installation date, is a 200 denial (denied_other) instead — on both the device-id + secret and the certificate channel, the former only once the secret is verified.
   */
  404: unknown;
  /**
   * Idempotency key reused with a different scan / secret, or the first call is still running (E-AUTH-094).
   */
  409: unknown;
  /**
   * Credential body mismatch (E-VIS-201) or a malformed NFC UID (E-VIS-202). An unreadable or forged QR is a 200 denial (denied_auth_failed, 「QRを読み取れませんでした。アプリのQRを再表示してください」), not a 422.
   */
  422: unknown;
};

export type GateDeviceControllerAuthenticateResponses = {
  /**
   * GateAuthResult: { eventId, decision, eventType, unlockDispatched, denialReasonCode, displayMessage, displayMessageEn, member, usedAt, clockSkewMs }. Denials are 200 too.
   */
  200: unknown;
};

