    sort?:
      | 'name'
      | 'status'
      | 'installedOn'
      | 'createdAt'
      | 'updatedAt'
      | 'ipAddress'
      | 'firmwareVersion'
      | 'controlPortCount'
      | 'connectedDeviceCount';
