export type AdminTransactionControllerListData = {
  body?: never;
  path?: never;
  query: {
    /**
     * true → pagination.totalAllItems = rows in the date window and the caller's scope with every optional filter reset. Omitted / false → no extra count.
     */
    includeTotalAll?: boolean;
    /**
     * 1–200, default 50.
     */
    limit?: number;
    page?: number;
    /**
     * JST day, inclusive. Must be a real calendar date.
     */
    fromDate: string;
    /**
     * JST day, inclusive. Max 12 months after fromDate (E-TXN-003).
     */
    toDate: string;
    transactionType?: Array<'sale' | 'payment' | 'refund' | 'write_off'>;
    /**
     * Max 100. Must be inside the caller's store scope (else 403 E-AUTH-101).
     */
    storeIds?: Array<string>;
    /**
     * v0.7: narrows EVERY transaction type — payment rows by payments.payment_method, refund rows by the method mapped from refunds.refund_method (sbps_void / sbps_partial_refund → sbps_credit, jaccs_manual → jaccs_bank, cashpost / cash / bank_transfer → same name), sale / write_off rows by the member's current primary payment method (financial_infos is_primary AND is_active AND not deleted; BR-TXN-001 #12). While it is set, rows with no method (no primary method) are excluded. Any type combination → 200 (E-TXN-009 is retired).
     */
    paymentMethod?: Array<
      | 'sbps_credit'
      | 'jaccs_bank'
      | 'card_onsite'
      | 'cash'
      | 'convenience_store'
      | 'sbps_link'
      | 'cashpost'
      | 'manual'
      | 'bank_transfer'
    >;
    memberId?: string;
    /**
     * 1–100 chars. Case-insensitive partial match on `last_name || first_name` (MD:183). AND with memberId. No match → no rows.
     */
    memberName?: string;
    /**
     * v0.8 — 1–60 chars after trim. Case-insensitive PREFIX match on `members.member_number` or `members.legacy_member_code` (the API-093 §3.2 `query` rule; `%` / `_` / `\` match literally). AND with the other filters. Applies to the list and the CSV export.
     */
    memberNumber?: string;
    status?: Array<
      | 'pending'
      | 'confirmed'
      | 'unconfirmed'
      | 'succeeded'
      | 'failed'
      | 'cancelled'
      | 'refunded'
      | 'partial_refund'
      | 'written_off'
    >;
    /**
     * Default transactionDate. Ties break on rowKey ascending (v0.7.3).
     */
    sortBy?: 'transactionDate' | 'memberName' | 'amountIncludingTax';
    /**
     * Default desc.
     */
    sortDir?: 'asc' | 'desc';
  };
  url: '/api/v1/admin/sales/transactions';
};

