export type AdminOptionControllerListData = {
  body?: never;
  path?: never;
  query?: {
    brandEnum?: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
    /**
     * All 9 `option_category` values are filterable — the list surfaces the 3 system-reserved tier-2 rows too (§12.8). Only the 6 tier-1 values are writable (§5.2 / §6.2).
     */
    category?:
      | 'supplement'
      | 'drink'
      | 'rental'
      | 'locker_option'
      | 'insurance'
      | 'service'
      | 'lesson_plan'
      | 'oneday_pass'
      | 'one_time_pass';
    paymentType?: 'monthly_billing' | 'per_use';
    /**
     * FR-002 3-way type (§12.7), expanded server-side into `paymentType` × `isAutoAssigned`. ANDs with an explicit `paymentType`, so a contradictory pair simply returns 0 rows.
     */
    optionType?: 'regular' | 'per_use' | 'auto_assigned';
    /**
     * Service category (★v0.8). Independent of the payment axis — `hydrogen_water` returns both the monthly and the per-use option.
     */
    subcategory?:
      | 'protein'
      | 'supplement'
      | 'tanning'
      | 'collagen'
      | 'hydrogen_water'
      | 'body_planner'
      | 'shower';
    usability?: 'unavailable' | 'add_cancel_only' | 'full' | 'change_cancel_only';
    /**
     * Daily-prorate filter (FR-S001). Omitted = both.
     */
    isProration?: boolean;
    isActive?: boolean;
    /**
     * Case-insensitive partial match on `name` OR `optionCode` (★v0.7). `%` and `_` are literal.
     */
    keyword?: string;
    /**
     * Only options linked to this store (`store_options`). Single UUID; an unknown one yields 0 rows rather than an error.
     */
    storeId?: string;
    /**
     * Omitted = the default fixed order. `feeMonthly` sorts on the stored tax-inclusive value (API-085 v0.12).
     */
    sort?: 'name' | 'feeMonthly' | 'createdAt';
    /**
     * Default `asc`; ignored when `sort` is omitted.
     */
    order?: 'asc' | 'desc';
    /**
     * CONV-001 §3.4.1 — adds `pagination.totalAllItems`, the count with every optional filter cleared (the 「全 N 件中 M 件」 banner). Costs an extra COUNT; omit it and none is issued.
     */
    includeTotalAll?: boolean;
    page?: number;
    limit?: number;
  };
  url: '/api/v1/admin/options';
};

