export type AdminStoreControllerListData = {
  body?: never;
  path?: never;
  query?: {
    /**
     * CONV `includeTotalAll` — adds `pagination.totalAllItems` (the count with every optional filter cleared). Omit it and no extra COUNT is issued.
     */
    includeTotalAll?: boolean;
    page?: number;
    limit?: number;
    sort?: 'code' | 'clubCode' | 'name' | 'createdAt';
    order?: 'asc' | 'desc';
    /**
     * Partial match on name / nameKana / code / clubCode / assigned territory name (v0.8). `%` and `_` are matched literally, not as wildcards.
     */
    keyword?: string;
    /**
     * Default `true`. `false` drops the internal store code (`S-###`) from the `keyword` match — for screens that do not show that code (Y-02 店舗一覧 shows `clubCode` as 店舗コード). Every code contains `-`, so with `true` a `-` keyword matches every store.
     */
    keywordIncludeCode?: boolean;
    brandEnum?: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
    brandGroup?: 'JOYFIT' | 'FIT365';
    /**
     * Prefecture code — romaji (`tokyo`, the spec form) **or** JIS X 0401 numeric (`13`, the form every stored row carries). Both are accepted and match the same stores, so either the value off a row or the value from the spec enum works.
     */
    prefecture?: string;
    status?: 'operating' | 'preparing' | 'temporarily_closed' | 'closed';
    /**
     * UUID or "direct".
     */
    fcCompanyId?: string;
    /**
     * v0.5 — stores assigned to this territory (unassigned stores never match).
     */
    territoryId?: string;
    /**
     * v0.5 — stores assigned to any territory directly under this area.
     */
    areaId?: string;
  };
  url: '/api/v1/admin/stores';
};

