export type AdminTrainerControllerListData = {
  body?: never;
  path?: never;
  query?: {
    /**
     * Adds `pagination.totalAllItems` — the count with the optional filters cleared, scope kept (CONV-001 §3.4.1).
     */
    includeTotalAll?: boolean;
    /**
     * Max 100. Partial match on the kanji / romanized names, nickname, and the full name with or without a space.
     */
    q?: string;
    /**
     * false = external contractors (no CRM account).
     */
    hasStaffAccount?: boolean;
    /**
     * Omit = both.
     */
    isActive?: boolean;
    /**
     * 1–24, default 6 — the past window for the derived filters / fields and the scope (future sessions always count).
     */
    scheduleWindowMonths?: number;
    /**
     * Schedule-derived. Outside your store scope → 403 E-TRN-100.
     */
    storeId?: string;
    /**
     * Additive (D-04 prototype ブランド filter): schedule-derived like `brand`, on the store's brand group — JOYFIT = Joyfit / Joyfit24 / JoyfitYoga / JoyfitPlus. Combinable with `brand` / `storeId` (all must match).
     */
    brandGroup?: 'JOYFIT' | 'FIT365';
    /**
     * Schedule-derived.
     */
    brand?: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
    primaryCoachType?: 'trainer' | 'instructor' | 'body_care_therapist';
    /**
     * Comma-separated: trainer, instructor, body_care_therapist (any match).
     */
    coachTypes?: string;
    /**
     * Default asc.
     */
    order?: 'asc' | 'desc';
    /**
     * Default lastName. `coachType` = the first role; `brand` = the first derived brand (alphabetical), trainers with none last. Ids are UUID v7, so createdAt is the id order.
     */
    sort?:
      | 'lastName'
      | 'createdAt'
      | 'updatedAt'
      | 'ratingAvg'
      | 'isActive'
      | 'coachType'
      | 'brand';
    /**
     * 1–100.
     */
    limit?: number;
    page?: number;
  };
  url: '/api/v1/admin/trainers';
};

