export type AdminLessonScheduleControllerListSchedulesData = {
  body?: never;
  path?: never;
  query?: {
    /**
     * Default `asc`.
     */
    order?: 'asc' | 'desc';
    /**
     * Default `scheduledDate` (then startTime).
     */
    sort?: 'scheduledDate' | 'startTime' | 'createdAt';
    limit?: number;
    page?: number;
    /**
     * DEPRECATED pre-spec toggle: `true` lists cancelled sessions alongside the live ones. Use `isCancelled`.
     *
     * @deprecated
     */
    includeCancelled?: boolean;
    /**
     * Cancel-flag filter, default false; `true` lists only cancelled sessions. Wins over `includeCancelled` when both are sent.
     */
    isCancelled?: boolean;
    /**
     * Mode A (true) / mode B (false). Omit for both.
     */
    isPublished?: boolean;
    /**
     * Inclusive. Default `from` + 7 days; at most `from` + 3 calendar months.
     */
    to?: string;
    /**
     * Inclusive. Default today (JST); at most 365 days back.
     */
    from?: string;
    lessonType?: 'studio' | 'personal_training' | 'body_care';
    lessonId?: string;
    studioId?: string;
    /**
     * Comma-separated trainer UUIDs (max 20): schedules where ANY of them is assigned. Exclusive with `trainerId`; ignored with `view=trainer-self` and for a `trainer` caller.
     */
    trainerIds?: Array<string>;
    /**
     * Schedules where this trainer is ANY of the assigned trainers. Exclusive with `trainerIds`; ignored with `view=trainer-self` and for a `trainer` caller.
     */
    trainerId?: string;
    /**
     * `view=area` only: an active Y-15 `area` node; the server resolves its stores (those of its active territories — §6.13.4). For `view=area` send exactly one of `areaId` / a store list.
     */
    areaId?: string;
    /**
     * Target store. Required for every view except `trainer-self` and `area` — 400 E-VAL-001 without it (§4.1), for every role including a `trainer` caller (a trainer wanting its own schedules without a store sends `view=trainer-self`) — unless `trainerId` / `trainerIds` is given (v0.15): then the rows are every store in your read scope (HQ: all; manager: staff_stores; staff / observer: own stores; trainer: own sessions only). With `view=area`, a comma-separated list of store UUIDs (max 40) — exclusive with `areaId` (v0.12: the separate `storeIds` parameter is gone; sending it is 400 E-VAL-001).
     */
    storeId?: string;
    /**
     * Default `store`. `trainer-self` forces your own trainer (FR-002); `area` takes `areaId` or a comma-list `storeId`. `trainer` is the DEPRECATED pre-spec name: it forces nothing (the `trainerId` you pass is the filter) and, like `store`, needs a `storeId`. A `trainer` CALLER is held to its own trainer on every view (§6.10 Read row).
     */
    view?: 'store' | 'trainer-self' | 'area' | 'trainer';
    /**
     * Adds `pagination.totalAllItems` — the count with every optional parameter back to its default (window today … +7 days, cancelled hidden) and the store / area selection and the trainer-self scope (also a trainer caller's own-trainer scope) kept (CONV-001 §3.4.1). Omit it and the extra COUNT is not run.
     */
    includeTotalAll?: boolean;
  };
  url: '/api/v1/admin/lesson-schedules';
};

