export type AdminQuestionnaireControllerListData = {
  body?: never;
  path?: never;
  query?: {
    page?: number;
    limit?: number;
    category?: 'lifecycle' | 'operational' | 'counseling';
    status?: 'active' | 'inactive';
    /**
     * mst_questionnaire_triggers.code
     */
    triggerCode?: string;
    /**
     * One sub-brand: the questionnaire is tagged with it.
     */
    brandEnum?: 'Joyfit' | 'Joyfit24' | 'JoyfitYoga' | 'JoyfitPlus' | 'Fit365';
    /**
     * Brand **group** — the questionnaire is tagged with ANY sub-brand of it (JOYFIT = Joyfit / Joyfit24 / JoyfitYoga / JoyfitPlus, FIT365 = Fit365). With `brandEnum` too, the questionnaire must match both.
     */
    brandGroup?: 'JOYFIT' | 'FIT365';
    nameQuery?: string;
    /**
     * Default `createdAt`. Computed keys sort across the whole list; nulls last.
     */
    sort?:
      | 'code'
      | 'name'
      | 'category'
      | 'questionCount'
      | 'responseCount'
      | 'responseRatePct'
      | 'lastAnsweredAt'
      | 'status'
      | 'createdAt'
      | 'updatedAt';
    /**
     * Default `desc`.
     */
    order?: 'asc' | 'desc';
    /**
     * Adds `pagination.totalAllItems` (every optional filter cleared). Omit it and no extra COUNT is issued.
     */
    includeTotalAll?: boolean;
  };
  url: '/api/v1/admin/questionnaires';
};

