export type LegacyUsersControllerUpdateData = {
  body: LegacyUserUpdateDto;
  path?: never;
  query?: never;
  url: '/api/v1/users/me';
};

export type LegacyUsersControllerUpdateErrors = {
  /**
   * Body failed schema validation / no fields supplied (E-VAL-001).
   */
  400: unknown;
  /**
   * Missing/invalid/expired Fitness JWT (E-AUTH-002 / E-AUTH-003).
   */
  401: unknown;
  /**
   * Not editable for this member: Type C / vendor (E-AUTH-100), Yamauchi field on Type B (E-MEM-100), or email/phone on the App Store review account (E-MEM-206).
   */
  403: unknown;
  /**
   * Member not found / soft-deleted (E-MEM-001).
   */
  404: unknown;
  /**
   * New email/phone already registered to a Yamauchi account (E-MEM-203 / E-MEM-204) — including the member's own: a "change" to the current email/phone is refused the same way, without contacting Yamauchi.
   */
  409: unknown;
  /**
   * Non-active Type B member cannot edit (E-MEM-200).
   */
  422: unknown;
  /**
   * Yamauchi User/System API timed out (E-EXT-001), or failed / refused the call in a way that is not the member's doing, e.g. the System API IP allowlist (E-EXT-002).
   */
  502: unknown;
  /**
   * Yamauchi under planned maintenance (E-EXT-110).
   */
  503: unknown;
};

export type LegacyUsersControllerUpdateResponses = {
  /**
   * The updated account. **Only for changes that apply immediately** — an email or phone change returns 202 with a pending-change body instead.
   */
  200: LegacyUserInfoResponseDto;
  /**
   * **A different body from the 200**: the change is NOT applied yet, an OTP was sent, and `pendingField` says which field is waiting. Branch on the status before assuming you got an account object.
   */
  202: PendingChangeResponseDto;
};

export type LegacyUsersControllerUpdateResponse =
  LegacyUsersControllerUpdateResponses[keyof LegacyUsersControllerUpdateResponses];

